CREATE OR REPLACE FUNCTION public.contact_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c supply_candidates; f supply_facts; call gov_calls; proof gov_evidence;
        binding supply_operations; cfg gov_configs; root contact_cases; out_fact supply_facts;
        contact_op contact_operations;
BEGIN
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'immutable contact record'; END IF;
 IF TG_TABLE_NAME='contact_cases' THEN
  SELECT * INTO c FROM supply_candidates WHERE id=NEW.candidate_id;
  SELECT * INTO f FROM supply_facts WHERE id=NEW.source_fact_id;
  SELECT * INTO call FROM gov_calls WHERE id=NEW.brave_call_id;
  SELECT * INTO proof FROM gov_evidence WHERE id=NEW.result_evidence_id;
  SELECT * INTO cfg FROM gov_configs WHERE id=NEW.config_id;
  SELECT * INTO contact_op FROM contact_operations WHERE operation_id=call.operation_id;
  IF c.experiment_id IS DISTINCT FROM NEW.experiment_id OR f.identity_id IS DISTINCT FROM c.identity_id
     OR call.experiment_id IS DISTINCT FROM NEW.experiment_id OR call.config_id IS DISTINCT FROM NEW.config_id
     OR call.config_version IS DISTINCT FROM NEW.config_version OR call.grant_id IS DISTINCT FROM NEW.grant_id
     OR call.grant_version IS DISTINCT FROM NEW.grant_version OR call.state<>'FINAL'
     OR contact_op.candidate_id IS DISTINCT FROM NEW.candidate_id OR contact_op.config_id IS DISTINCT FROM NEW.config_id
     OR cfg.capability NOT IN ('BRAVE_LOCAL_DISCOVERY','BRAVE_COMPANY_DISCOVERY')
     OR proof.call_id IS DISTINCT FROM call.id OR proof.kind<>'PROVIDER_RESULT'
     OR (NEW.presence='PRESENT' AND f.kind<>'SOURCE_EMAIL')
     OR (NEW.presence='ABSENT' AND f.kind<>'EMAIL_ABSENT')
     OR (NEW.presence='NOT_AVAILABLE' AND f.kind<>'SOURCE_FAILURE')
     OR ((call.result_metadata->>'status'='SUCCEEDED') IS DISTINCT FROM (NEW.presence<>'NOT_AVAILABLE'))
     OR NEW.observed_at IS DISTINCT FROM (call.result_metadata->>'finished_at')::timestamptz
     OR NEW.valid_until>least(f.valid_until,(SELECT expires_at FROM gov_grants WHERE id=NEW.grant_id AND version=NEW.grant_version),(call.attribution->>'deadline')::timestamptz)
  THEN RAISE EXCEPTION 'invalid contact source binding'; END IF;
 ELSIF TG_TABLE_NAME='contact_operations' THEN
  SELECT * INTO binding FROM supply_operations WHERE operation_id=NEW.operation_id;
  SELECT * INTO cfg FROM gov_configs WHERE id=NEW.config_id;
  SELECT * INTO c FROM supply_candidates WHERE id=NEW.candidate_id;
  SELECT * INTO root FROM contact_cases WHERE candidate_id=NEW.case_id;
  SELECT * INTO f FROM supply_facts WHERE id=NEW.source_fact_id;
  IF binding.kind<>'CONTACT' OR binding.candidate_id IS DISTINCT FROM NEW.candidate_id
     OR binding.config_id IS DISTINCT FROM NEW.config_id OR binding.config_version IS DISTINCT FROM NEW.config_version
     OR cfg.capability IS DISTINCT FROM NEW.capability
     OR (NEW.case_id IS NOT NULL AND (root.experiment_id IS DISTINCT FROM NEW.experiment_id OR NEW.case_id IS DISTINCT FROM NEW.candidate_id))
     OR (NEW.source_fact_id IS NOT NULL AND (f.kind<>'SOURCE_EMAIL' OR f.identity_id IS DISTINCT FROM c.identity_id))
     OR (NEW.verification_policy_id IS NOT NULL AND NEW.verification_policy_id IS DISTINCT FROM (SELECT verification_policy_id FROM supply_plans WHERE experiment_id=NEW.experiment_id))
  THEN RAISE EXCEPTION 'invalid contact operation binding'; END IF;
 ELSE
 SELECT * INTO call FROM gov_calls WHERE id=NEW.call_id;
  SELECT * INTO proof FROM gov_evidence WHERE id=NEW.result_evidence_id;
  SELECT * INTO out_fact FROM supply_facts WHERE id=NEW.output_fact_id;
  SELECT * INTO contact_op FROM contact_operations WHERE operation_id=NEW.operation_id;
  SELECT * INTO c FROM supply_candidates WHERE id=NEW.candidate_id;
  SELECT * INTO root FROM contact_cases WHERE candidate_id=NEW.candidate_id;
  IF call.operation_id IS DISTINCT FROM NEW.operation_id OR call.experiment_id IS DISTINCT FROM NEW.experiment_id
     OR call.state<>'FINAL' OR call.result_metadata->>'status'<>'SUCCEEDED'
     OR proof.call_id IS DISTINCT FROM call.id OR proof.kind<>'PROVIDER_RESULT'
     OR NEW.observed_at IS DISTINCT FROM (call.result_metadata->>'finished_at')::timestamptz
     OR NEW.valid_until>least(root.valid_until,coalesce(out_fact.valid_until,root.valid_until),(call.attribution->>'deadline')::timestamptz)
     OR (NEW.output_fact_id IS NOT NULL AND (out_fact.experiment_id IS DISTINCT FROM NEW.experiment_id OR out_fact.identity_id IS DISTINCT FROM c.identity_id))
     OR (contact_op.capability='HUNTER_EMAIL_VERIFICATION' AND NEW.outcome NOT IN ('VALID','INVALID','ACCEPT_ALL','UNKNOWN','TEMPORARY_FAILURE','TRANSIENT'))
     OR (contact_op.capability<>'HUNTER_EMAIL_VERIFICATION' AND NEW.outcome NOT IN ('FOUND','NOT_FOUND','TRANSIENT'))
     OR (contact_op.capability='HUNTER_EMAIL_VERIFICATION' AND NEW.outcome='VALID' AND (out_fact.kind IS DISTINCT FROM 'VERIFIED' OR out_fact.contact_ref IS DISTINCT FROM contact_op.source_fact_id OR out_fact.policy_ref IS DISTINCT FROM contact_op.verification_policy_id))
     OR (contact_op.capability='HUNTER_EMAIL_VERIFICATION' AND NEW.outcome IN ('INVALID','ACCEPT_ALL','UNKNOWN') AND (out_fact.kind IS DISTINCT FROM 'VERIFICATION_REJECTED' OR out_fact.contact_ref IS DISTINCT FROM contact_op.source_fact_id OR out_fact.policy_ref IS DISTINCT FROM contact_op.verification_policy_id))
     OR (contact_op.capability='HUNTER_EMAIL_VERIFICATION' AND NEW.outcome IN ('TEMPORARY_FAILURE','TRANSIENT') AND NEW.output_fact_id IS NOT NULL)
     OR (contact_op.capability<>'HUNTER_EMAIL_VERIFICATION' AND NEW.outcome='FOUND' AND out_fact.kind IS DISTINCT FROM 'SOURCE_EMAIL')
     OR (contact_op.capability<>'HUNTER_EMAIL_VERIFICATION' AND NEW.outcome IN ('NOT_FOUND','TRANSIENT') AND NEW.output_fact_id IS NOT NULL)
  THEN RAISE EXCEPTION 'invalid contact attempt binding'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.gov_binding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE cfg gov_configs; p gov_prices; g gov_grants; ca gov_calls; a gov_budget_accounts; f gov_fx;
BEGIN
 IF TG_TABLE_NAME='gov_config_prices' THEN
  SELECT * INTO cfg FROM gov_configs WHERE id=NEW.config_id;
  SELECT * INTO p FROM gov_prices WHERE id=NEW.price_id;
  SELECT * INTO f FROM gov_fx WHERE id=cfg.fx_id;
  IF cfg.capability IS DISTINCT FROM p.capability OR p.currency IS DISTINCT FROM f.currency OR p.model_identifier IS DISTINCT FROM (cfg.data->>'model_identifier') THEN
   RAISE EXCEPTION 'governance price binding' USING ERRCODE='23514';
  END IF;
 ELSIF TG_TABLE_NAME='gov_calls' THEN
  PERFORM gov_validate_call_json(NEW);
  SELECT * INTO cfg FROM gov_configs WHERE id=NEW.config_id;
  SELECT * INTO g FROM gov_grants WHERE id=NEW.grant_id AND version=NEW.grant_version;
  SELECT * INTO f FROM gov_fx WHERE id=cfg.fx_id;
  IF cfg.capability IS DISTINCT FROM g.capability OR cfg.account IS DISTINCT FROM g.account OR NEW.currency IS DISTINCT FROM f.currency THEN
   RAISE EXCEPTION 'governance call binding' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['state','accrued','accrued_ils','dispatch_at','lease_until','token','finished_at','policy_id','error','result_metadata']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['state','accrued','accrued_ils','dispatch_at','lease_until','token','finished_at','policy_id','error','result_metadata']) THEN
   RAISE EXCEPTION 'immutable governance intent' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND NOT (NEW.state=OLD.state OR
      (OLD.state='RESERVED' AND NEW.state IN ('DISPATCHED','RELEASED')) OR
      (OLD.state='DISPATCHED' AND NEW.state IN ('RECONCILING','FINAL')) OR
      (OLD.state='RECONCILING' AND NEW.state='FINAL')) THEN
   RAISE EXCEPTION 'governance state transition' USING ERRCODE='23514';
  END IF;
 ELSIF TG_TABLE_NAME='gov_usage' THEN
  SELECT * INTO ca FROM gov_calls WHERE id=NEW.call_id;
  SELECT * INTO p FROM gov_prices WHERE id=NEW.price_id;
  IF p.component IS DISTINCT FROM NEW.component OR p.currency IS DISTINCT FROM NEW.currency OR NOT EXISTS
     (SELECT 1 FROM gov_config_prices WHERE config_id=ca.config_id AND price_id=NEW.price_id) THEN
   RAISE EXCEPTION 'governance usage binding' USING ERRCODE='23514';
  END IF;
 ELSIF TG_TABLE_NAME='gov_allocations' THEN
  SELECT * INTO ca FROM gov_calls WHERE id=NEW.call_id;
  SELECT * INTO a FROM gov_budget_accounts WHERE id=NEW.account_id;
  SELECT * INTO cfg FROM gov_configs WHERE id=ca.config_id;
  IF (a.experiment_id IS NOT NULL AND a.experiment_id<>ca.experiment_id) OR
     (a.workflow_id IS NOT NULL AND a.workflow_id<>ca.workflow_id) OR
     (a.operation_id IS NOT NULL AND a.operation_id<>ca.operation_id) OR
     (a.provider IS NOT NULL AND a.provider<>cfg.data->'intended_use'->>'provider') OR
     a.currency NOT IN (ca.currency,'ILS') OR NEW.amount <> (CASE WHEN a.currency='ILS' THEN ca.reserved_ils ELSE ca.reserved END) THEN
   RAISE EXCEPTION 'governance allocation binding' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.gov_proof_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE proof gov_evidence; required_kind text;
BEGIN
 SELECT * INTO proof FROM gov_evidence WHERE id=NEW.evidence_id;
 required_kind := CASE TG_TABLE_NAME WHEN 'gov_prices' THEN 'PRICE' WHEN 'gov_fx' THEN 'FX' WHEN 'gov_grants' THEN 'GRANT'
   WHEN 'gov_grant_events' THEN 'GRANT_EVENT' WHEN 'gov_policies' THEN 'CONTROL' WHEN 'gov_cash_entries' THEN 'INVOICE' ELSE 'RECONCILIATION' END;
 IF proof.id IS NULL OR NOT (proof.kind=required_kind OR (TG_TABLE_NAME='gov_settlements' AND proof.kind='PROVIDER_RESULT')) THEN
  RAISE EXCEPTION 'governance proof kind' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME IN ('gov_settlements','gov_cash_entries') THEN
  IF proof.call_id IS DISTINCT FROM NEW.call_id THEN
   RAISE EXCEPTION 'governance proof scope' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.openai_premium_approval_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'OpenAI premium approval cannot be deleted'; END IF;
 IF (to_jsonb(NEW)-ARRAY['revoked_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['revoked_at'])
    OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
    OR (NEW.revoked_at IS NOT NULL AND NEW.revoked_at < OLD.approved_at) THEN
  RAISE EXCEPTION 'OpenAI premium approval is immutable except first revocation';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.openai_run_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'OpenAI run intent cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.outcome<>'READY' THEN RAISE EXCEPTION 'OpenAI run must begin READY'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['call_id','outcome','output_hash','finished_at'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['call_id','outcome','output_hash','finished_at']) THEN
  RAISE EXCEPTION 'OpenAI run identity is immutable';
 END IF;
 IF NOT ((OLD.outcome='READY' AND NEW.outcome NOT IN ('READY','RECOVERING'))
      OR (OLD.outcome='READY' AND NEW.outcome='RECOVERING')
      OR (OLD.outcome='RECOVERING' AND NEW.outcome NOT IN ('READY','RECOVERING'))) THEN
  RAISE EXCEPTION 'OpenAI run result is immutable';
 END IF;
 IF NEW.call_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM gov_calls c WHERE c.id=NEW.call_id
   AND c.idempotency_key=NEW.idempotency_key AND c.config_id=NEW.config_id
   AND c.config_version=NEW.config_version AND c.experiment_id=NEW.experiment_id
   AND c.workflow_id=NEW.workflow_id AND c.operation_id=NEW.operation_id
 ) THEN RAISE EXCEPTION 'OpenAI run call lineage mismatch'; END IF;
 IF NEW.outcome='SUCCEEDED' AND (NEW.output_hash IS NULL OR NOT EXISTS(
  SELECT 1 FROM gov_calls c WHERE c.id=NEW.call_id AND c.state='FINAL'
   AND c.result_metadata->>'status'='SUCCEEDED'
 )) THEN RAISE EXCEPTION 'OpenAI succeeded run requires final usage ledger'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_calibration_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE proposal record_calibration_proposals; decision record_calibration_decisions;
 acceptance record_offer_acceptances; fulfillment record_calibration_fulfillments;
 obligation record_calibration_obligations;
 qualification record_qualification_decisions; package record_offer_packages;
BEGIN
 IF TG_TABLE_NAME='record_calibration_proposals' THEN
  PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
  SELECT * INTO acceptance FROM record_offer_acceptances WHERE id=NEW.base_offer_acceptance_id;
  IF acceptance.id IS NULL OR ROW(acceptance.experiment_id,acceptance.offer_id,acceptance.profile_id,acceptance.policy_id)
     IS DISTINCT FROM ROW(NEW.experiment_id,NEW.base_offer_id,NEW.base_profile_id,NEW.base_policy_id)
     OR NEW.base_offer_acceptance_id IS DISTINCT FROM
       (SELECT id FROM record_offer_acceptances WHERE experiment_id=NEW.experiment_id ORDER BY accepted_at DESC,id DESC LIMIT 1)
  THEN RAISE EXCEPTION 'exact calibration base required'; END IF;
 ELSIF TG_TABLE_NAME='record_calibration_proposal_evidence' THEN
  SELECT * INTO proposal FROM record_calibration_proposals WHERE id=NEW.proposal_id;
  SELECT * INTO qualification FROM record_qualification_decisions WHERE id=NEW.decision_id;
  IF proposal.id IS NULL OR qualification.id IS NULL
     OR ROW(qualification.candidate_id,qualification.dossier_id,qualification.matrix_id,qualification.experiment_id,qualification.offer_acceptance_id)
        IS DISTINCT FROM ROW(NEW.candidate_id,NEW.dossier_id,NEW.matrix_id,proposal.experiment_id,proposal.base_offer_acceptance_id)
     OR NEW.finding_code<>proposal.mismatch_code
     OR NOT (NEW.finding_code,qualification.outcome) IN (
       ('TECHNICAL_MISMATCH','REJECTED_TECHNICAL_MISMATCH'),
       ('ECONOMIC_MISMATCH','REJECTED_ECONOMIC_MISMATCH'),
       ('BUYER_MISMATCH','REJECTED_BUYER_MISMATCH'))
     OR NOT NEW.finding_code=ANY(qualification.finding_codes)
  THEN RAISE EXCEPTION 'exact calibration evidence required'; END IF;
 ELSIF TG_TABLE_NAME='record_calibration_decisions' THEN
  PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
  SELECT * INTO proposal FROM record_calibration_proposals WHERE id=NEW.proposal_id;
  IF proposal.id IS NULL
     OR ROW(NEW.experiment_id,NEW.base_offer_acceptance_id,NEW.base_offer_id,NEW.base_profile_id,NEW.base_policy_id,NEW.evidence_hash)
        IS DISTINCT FROM ROW(proposal.experiment_id,proposal.base_offer_acceptance_id,proposal.base_offer_id,proposal.base_profile_id,proposal.base_policy_id,proposal.evidence_hash)
     OR NOT EXISTS(SELECT 1 FROM record_calibration_proposal_evidence e WHERE e.proposal_id=NEW.proposal_id GROUP BY e.proposal_id HAVING count(*)>=2 AND count(DISTINCT e.candidate_id)>=2)
     OR (NEW.outcome='ACCEPT' AND (EXISTS(SELECT 1 FROM record_qualification_cohorts WHERE experiment_id=NEW.experiment_id)
       OR EXISTS(SELECT 1 FROM record_calibration_decisions WHERE experiment_id=NEW.experiment_id AND outcome='ACCEPT')))
  THEN RAISE EXCEPTION 'invalid calibration decision'; END IF;
 ELSIF TG_TABLE_NAME='record_calibration_accepted_affected' THEN
  SELECT * INTO decision FROM record_calibration_decisions WHERE id=NEW.calibration_decision_id;
  SELECT * INTO qualification FROM record_qualification_decisions WHERE id=NEW.previous_decision_id;
  IF decision.id IS NULL OR qualification.id IS NULL OR decision.outcome<>'ACCEPT'
     OR ROW(qualification.candidate_id,qualification.dossier_id,qualification.matrix_id,qualification.experiment_id,qualification.offer_acceptance_id)
        IS DISTINCT FROM ROW(NEW.candidate_id,NEW.previous_dossier_id,NEW.previous_matrix_id,decision.experiment_id,decision.base_offer_acceptance_id)
     OR EXISTS(SELECT 1 FROM record_qualification_decisions later JOIN record_qualification_dossiers later_dossier ON later_dossier.id=later.dossier_id
       JOIN record_qualification_dossiers current_dossier ON current_dossier.id=qualification.dossier_id
       WHERE later.candidate_id=qualification.candidate_id AND later.offer_acceptance_id=decision.base_offer_acceptance_id
       AND later_dossier.version>current_dossier.version)
  THEN RAISE EXCEPTION 'invalid accepted calibration set'; END IF;
 ELSIF TG_TABLE_NAME='record_calibration_fulfillments' THEN
  PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
  SELECT * INTO decision FROM record_calibration_decisions WHERE id=NEW.calibration_decision_id;
  SELECT * INTO acceptance FROM record_offer_acceptances WHERE id=NEW.offer_acceptance_id;
  SELECT * INTO package FROM record_offer_packages WHERE id=acceptance.offer_id;
  IF decision.id IS NULL OR decision.outcome<>'ACCEPT' OR acceptance.id IS NULL OR package.id IS NULL
     OR ROW(NEW.experiment_id,NEW.base_offer_acceptance_id) IS DISTINCT FROM ROW(decision.experiment_id,decision.base_offer_acceptance_id)
     OR ROW(NEW.experiment_id,NEW.offer_id,NEW.profile_id,NEW.policy_id) IS DISTINCT FROM ROW(acceptance.experiment_id,acceptance.offer_id,acceptance.profile_id,acceptance.policy_id)
     OR package.calibration_decision_id IS DISTINCT FROM decision.id OR acceptance.id=decision.base_offer_acceptance_id
     OR acceptance.accepted_at<decision.decided_at
     OR acceptance.id IS DISTINCT FROM (SELECT id FROM record_offer_acceptances WHERE experiment_id=NEW.experiment_id ORDER BY accepted_at DESC,id DESC LIMIT 1)
     OR EXISTS(SELECT 1 FROM record_qualification_cohorts WHERE experiment_id=NEW.experiment_id)
  THEN RAISE EXCEPTION 'invalid calibration fulfillment'; END IF;
 ELSIF TG_TABLE_NAME='record_calibration_obligations' THEN
  SELECT * INTO fulfillment FROM record_calibration_fulfillments WHERE id=NEW.fulfillment_id;
  SELECT * INTO qualification FROM record_qualification_decisions WHERE id=NEW.previous_decision_id;
  IF fulfillment.id IS NULL OR qualification.id IS NULL
     OR ROW(NEW.experiment_id,NEW.required_offer_acceptance_id,NEW.candidate_id,NEW.previous_dossier_id,NEW.previous_matrix_id)
        IS DISTINCT FROM ROW(fulfillment.experiment_id,fulfillment.offer_acceptance_id,qualification.candidate_id,qualification.dossier_id,qualification.matrix_id)
     OR qualification.offer_acceptance_id<>fulfillment.base_offer_acceptance_id
 THEN RAISE EXCEPTION 'invalid requalification obligation'; END IF;
 ELSIF TG_TABLE_NAME='record_calibration_completions' THEN
  SELECT * INTO obligation FROM record_calibration_obligations WHERE id=NEW.obligation_id;
  SELECT * INTO fulfillment FROM record_calibration_fulfillments WHERE id=obligation.fulfillment_id;
  SELECT * INTO qualification FROM record_qualification_decisions WHERE id=NEW.decision_id;
  IF fulfillment.id IS NULL OR qualification.id IS NULL OR qualification.outcome NOT IN ('QUALIFIED_CONTACTABLE','PILOT_FIT_CONTACTABLE')
     OR ROW(qualification.candidate_id,qualification.experiment_id,qualification.offer_acceptance_id)
        IS DISTINCT FROM ROW(obligation.candidate_id,fulfillment.experiment_id,obligation.required_offer_acceptance_id)
     OR qualification.decided_at<fulfillment.fulfilled_at
  THEN RAISE EXCEPTION 'invalid requalification completion'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_conversation_booking_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE i record_conversation_booking_intents; c record_conversation_booking_confirmations;
BEGIN
 IF TG_TABLE_NAME='record_conversation_booking_confirmations' THEN
  SELECT * INTO i FROM record_conversation_booking_intents WHERE id=NEW.intent_id;
  IF i.slot_hash<>NEW.slot_hash OR i.attendee_hash<>NEW.attendee_hash
     OR NOT EXISTS(SELECT 1 FROM record_conversation_documents d JOIN record_conversation_evidence_spans s ON s.document_id=d.id WHERE d.id=NEW.source_document_id AND s.ordinal=NEW.source_span_ordinal AND d.conversation_id=i.conversation_id AND d.context_id=i.context_id) THEN RAISE EXCEPTION 'booking confirmation mismatch'; END IF;
 ELSE
  SELECT * INTO i FROM record_conversation_booking_intents WHERE id=NEW.intent_id;
  SELECT * INTO c FROM record_conversation_booking_confirmations WHERE id=NEW.confirmation_id;
  IF c.id IS NULL OR c.intent_id<>i.id OR i.slot_hash<>NEW.slot_hash OR i.attendee_hash<>NEW.attendee_hash OR c.slot_hash<>NEW.slot_hash OR c.attendee_hash<>NEW.attendee_hash
     OR NOT EXISTS(SELECT 1 FROM gov_evidence WHERE id=NEW.provider_evidence_id AND call_id=NEW.provider_call_id AND kind='PROVIDER_RESULT') THEN RAISE EXCEPTION 'booking observation mismatch'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_conversation_handoff_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record_conversations; t record_conversation_turn_contexts; i record_conversation_booking_intents; o record_conversation_booking_observations;
BEGIN
 SELECT * INTO c FROM record_conversations WHERE id=NEW.conversation_id;
 SELECT * INTO t FROM record_conversation_turn_contexts WHERE id=NEW.context_id;
 IF c.id IS NULL OR t.id IS NULL OR c.experiment_id<>NEW.experiment_id
    OR t.experiment_id<>NEW.experiment_id OR t.conversation_id<>NEW.conversation_id
    OR NOT EXISTS(SELECT 1 FROM record_conversation_documents d JOIN record_conversation_evidence_spans s ON s.document_id=d.id
      WHERE d.id=NEW.source_document_id AND s.ordinal=NEW.source_span_ordinal AND d.experiment_id=NEW.experiment_id AND d.conversation_id=NEW.conversation_id AND d.context_id=NEW.context_id)
    OR (NEW.offer_acceptance_id,NEW.offer_id,NEW.profile_id,NEW.policy_id,NEW.recipient_id)
      IS DISTINCT FROM (t.offer_acceptance_id,t.offer_id,t.profile_id,t.policy_id,c.recipient_id)
 THEN RAISE EXCEPTION 'handoff lineage mismatch'; END IF;
 IF NEW.kind='MEETING_BOOKING' THEN
  SELECT * INTO o FROM record_conversation_booking_observations WHERE id=NEW.booking_observation_id;
  IF o.id IS NOT NULL THEN SELECT * INTO i FROM record_conversation_booking_intents WHERE id=o.intent_id; END IF;
  IF o.id IS NULL OR i.id IS NULL
     OR (i.experiment_id,i.conversation_id,i.context_id,i.offer_acceptance_id,i.offer_id,i.profile_id,i.policy_id,i.recipient_id)
       IS DISTINCT FROM (NEW.experiment_id,NEW.conversation_id,NEW.context_id,NEW.offer_acceptance_id,NEW.offer_id,NEW.profile_id,NEW.policy_id,NEW.recipient_id)
     OR NOT EXISTS(SELECT 1 FROM record_conversation_booking_confirmations b
       WHERE b.id=o.confirmation_id AND b.intent_id=i.id
         AND (b.source_document_id,b.source_span_ordinal)=(NEW.source_document_id,NEW.source_span_ordinal))
  THEN RAISE EXCEPTION 'booking handoff mismatch'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_conversation_lock_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE current record_conversation_lock_events;
BEGIN
 PERFORM 1 FROM record_conversations WHERE id=NEW.conversation_id AND experiment_id=NEW.experiment_id FOR UPDATE;
 SELECT * INTO current FROM record_conversation_lock_events WHERE conversation_id=NEW.conversation_id ORDER BY event_ordinal DESC LIMIT 1;
 IF NEW.event_kind='ACTIVATE' THEN
  IF current.id IS NOT NULL AND current.event_kind='ACTIVATE' THEN RAISE EXCEPTION 'active automation lock exists'; END IF;
 ELSIF current.id IS NULL OR current.event_kind<>'ACTIVATE' OR NEW.prior_lock_id<>current.id OR NEW.lock_kind<>current.lock_kind THEN
  RAISE EXCEPTION 'invalid lock release';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_conversation_operator_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record_conversations; l record_conversation_lock_events;
BEGIN
 SELECT * INTO c FROM record_conversations WHERE id=NEW.conversation_id;
 SELECT * INTO l FROM record_conversation_lock_events WHERE conversation_id=NEW.conversation_id ORDER BY event_ordinal DESC LIMIT 1;
 IF NOT EXISTS(SELECT 1 FROM record_conversation_turn_contexts WHERE id=NEW.context_id AND conversation_id=NEW.conversation_id)
    OR l.id IS NULL OR l.event_kind<>'ACTIVATE' OR l.lock_kind<>'MANUAL_TAKEOVER' OR l.id<>NEW.active_lock_event_id
    OR NOT EXISTS(SELECT 1 FROM record_operators WHERE id=NEW.operator_id AND status='ACTIVE') THEN RAISE EXCEPTION 'manual operator authority required'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_conversation_operator_message_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record_conversations; l record_conversation_lock_events;
BEGIN
 SELECT * INTO c FROM record_conversations WHERE id=NEW.conversation_id;
 SELECT * INTO l FROM record_conversation_lock_events WHERE conversation_id=NEW.conversation_id ORDER BY event_ordinal DESC LIMIT 1;
 IF NOT EXISTS(SELECT 1 FROM record_conversation_turn_contexts WHERE id=NEW.context_id AND conversation_id=NEW.conversation_id)
    OR l.id IS NULL OR l.event_kind<>'ACTIVATE' OR l.lock_kind<>'MANUAL_TAKEOVER' OR l.id<>NEW.active_lock_event_id
    OR NOT EXISTS(SELECT 1 FROM record_operators WHERE id=NEW.operator_id AND status='ACTIVE')
    OR (c.organization_id,c.recipient_id,c.recipient_source_id,c.thread_identity_hash) <> (NEW.organization_id,NEW.recipient_id,NEW.recipient_source_id,NEW.thread_identity_hash) THEN RAISE EXCEPTION 'operator message lineage mismatch'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_conversation_referral_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r record_conversation_referrals;
BEGIN
 IF TG_TABLE_NAME='record_conversation_referrals' THEN
  IF NOT EXISTS(SELECT 1 FROM record_conversation_turn_contexts t JOIN record_conversation_documents d ON d.id=NEW.source_document_id JOIN record_conversation_evidence_spans s ON s.document_id=d.id AND s.ordinal=NEW.source_span_ordinal WHERE t.id=NEW.context_id AND t.conversation_id=NEW.conversation_id AND d.conversation_id=NEW.conversation_id AND d.context_id=NEW.context_id) THEN RAISE EXCEPTION 'referral source mismatch'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO r FROM record_conversation_referrals WHERE id=NEW.referral_id;
 IF NOT EXISTS(SELECT 1 FROM record_conversation_documents d JOIN record_conversation_evidence_spans s ON s.document_id=d.id
   WHERE d.id=NEW.document_id AND s.ordinal=NEW.span_ordinal AND d.conversation_id=r.conversation_id)
   OR (NEW.role='RELEVANCE' AND (NEW.document_id,NEW.span_ordinal)<>(r.source_document_id,r.source_span_ordinal)) THEN RAISE EXCEPTION 'referral evidence mismatch'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_cycle_transition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE current_state record_cycle_states; acceptance record_idea_acceptances;
 attempt record_research_attempts; accepted_artifact record_artifacts;
 command record_commands; committed record_verdicts; expected_state TEXT;
 offer_run record_offer_design_runs; offer_decision record_offer_design_decisions;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable cycle transition'; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 SELECT * INTO current_state FROM record_cycle_states WHERE cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id FOR UPDATE;
 SELECT * INTO acceptance FROM record_idea_acceptances WHERE id=NEW.idea_acceptance_id
  AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id
  AND artifact_id=NEW.idea_artifact_id AND artifact_kind=NEW.idea_kind
  AND artifact_version=NEW.idea_version AND artifact_hash=NEW.idea_hash;
 SELECT * INTO attempt FROM record_research_attempts WHERE id=NEW.research_attempt_id AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id;
 SELECT * INTO accepted_artifact FROM record_artifacts WHERE id=NEW.idea_artifact_id AND experiment_id=NEW.experiment_id AND kind=NEW.idea_kind AND version=NEW.idea_version AND content_hash=NEW.idea_hash;
 SELECT * INTO command FROM record_commands WHERE id=NEW.command_id;
 IF current_state.cycle_id IS NULL OR current_state.state IS DISTINCT FROM NEW.from_state
  OR current_state.transition_ordinal+1 IS DISTINCT FROM NEW.ordinal
  OR acceptance.id IS NULL OR attempt.id IS NULL OR accepted_artifact.id IS NULL
  OR command.id IS NULL OR command.experiment_id IS DISTINCT FROM NEW.experiment_id
 THEN RAISE EXCEPTION 'invalid cycle transition lineage'; END IF;
 IF NEW.from_state='PROCEED_TO_OFFER' THEN
  SELECT * INTO offer_run FROM record_offer_design_runs WHERE id=NEW.offer_design_run_id AND experiment_id=NEW.experiment_id;
  SELECT * INTO committed FROM record_verdicts WHERE id=NEW.verdict_id AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id AND attempt_id=NEW.research_attempt_id;
  IF NEW.to_state<>'OFFER_DESIGN' OR NEW.offer_design_decision_id IS NOT NULL
   OR offer_run.id IS NULL OR offer_run.cycle_id IS DISTINCT FROM NEW.cycle_id OR offer_run.verdict_id IS DISTINCT FROM NEW.verdict_id
   OR committed.id IS NULL OR committed.verdict<>'PROCEED_TO_OFFER'
   OR command.kind<>'START_OFFER_DESIGN' OR command.result_id IS DISTINCT FROM offer_run.id
  THEN RAISE EXCEPTION 'invalid offer design start transition'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.from_state='OFFER_DESIGN' THEN
  SELECT * INTO offer_run FROM record_offer_design_runs WHERE id=NEW.offer_design_run_id AND experiment_id=NEW.experiment_id;
  SELECT * INTO offer_decision FROM record_offer_design_decisions WHERE id=NEW.offer_design_decision_id AND run_id=NEW.offer_design_run_id AND experiment_id=NEW.experiment_id;
  SELECT * INTO committed FROM record_verdicts WHERE id=NEW.verdict_id AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id AND attempt_id=NEW.research_attempt_id;
  expected_state:=CASE offer_decision.outcome WHEN 'ACCEPT' THEN 'OFFER_ACCEPTED' WHEN 'TARGETED_RESEARCH_REQUIRED' THEN 'RETURN_FOR_TARGETED_RESEARCH' WHEN 'IDEA_REFINEMENT_RECOMMENDED' THEN 'WAITING_FOR_OPERATOR_INPUT' WHEN 'WAITING_FOR_OPERATOR_INPUT' THEN 'WAITING_FOR_OPERATOR_INPUT' END;
  IF offer_run.id IS NULL OR offer_run.cycle_id IS DISTINCT FROM NEW.cycle_id OR offer_run.verdict_id IS DISTINCT FROM NEW.verdict_id
   OR offer_decision.id IS NULL OR committed.id IS NULL OR committed.verdict<>'PROCEED_TO_OFFER'
   OR NEW.to_state IS DISTINCT FROM expected_state
   OR (offer_decision.outcome='ACCEPT' AND (
      command.kind<>'ACCEPT_OFFER' OR NOT EXISTS(
        SELECT 1 FROM record_offer_acceptances offer_acceptance
        JOIN record_offer_packages package ON package.id=offer_acceptance.offer_id
        JOIN record_offer_qualification_profiles profile ON profile.id=offer_acceptance.profile_id AND profile.offer_id=package.id
        JOIN record_initial_outreach_policies policy ON policy.id=offer_acceptance.policy_id AND policy.offer_id=package.id
        WHERE offer_acceptance.id=command.result_id AND package.offer_design_run_id=offer_run.id
      )
   ))
   OR (offer_decision.outcome='TARGETED_RESEARCH_REQUIRED' AND command.kind<>'RETURN_FOR_TARGETED_RESEARCH')
   OR (offer_decision.outcome IN ('IDEA_REFINEMENT_RECOMMENDED','WAITING_FOR_OPERATOR_INPUT') AND command.kind<>'DECIDE_OFFER_DESIGN')
  THEN RAISE EXCEPTION 'invalid offer design decision transition'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.from_state='WAITING_FOR_OPERATOR_INPUT' THEN
  SELECT * INTO offer_run FROM record_offer_design_runs WHERE id=NEW.offer_design_run_id AND experiment_id=NEW.experiment_id;
  SELECT * INTO offer_decision FROM record_offer_design_decisions WHERE id=NEW.offer_design_decision_id AND run_id=NEW.offer_design_run_id AND experiment_id=NEW.experiment_id;
  SELECT * INTO committed FROM record_verdicts WHERE id=NEW.verdict_id AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id AND attempt_id=NEW.research_attempt_id;
  IF NEW.to_state<>'RETURN_FOR_IDEA_REFINEMENT' OR offer_run.id IS NULL OR offer_decision.id IS NULL
   OR offer_decision.outcome<>'IDEA_REFINEMENT_RECOMMENDED' OR committed.verdict<>'PROCEED_TO_OFFER'
   OR command.kind<>'CONFIRM_OFFER_IDEA_REFINEMENT' OR command.result_id IS DISTINCT FROM NEW.offer_design_decision_id
  THEN RAISE EXCEPTION 'invalid offer idea-refinement return'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.ordinal=1 THEN
  IF attempt.ordinal<>1 OR NEW.cycle_id IS DISTINCT FROM (SELECT id FROM record_cycles WHERE experiment_id=NEW.experiment_id ORDER BY ordinal DESC LIMIT 1)
   OR EXISTS(SELECT 1 FROM record_artifacts later WHERE later.logical_id=accepted_artifact.logical_id AND later.version>accepted_artifact.version)
   OR EXISTS(SELECT 1 FROM record_artifact_dispositions disposition WHERE disposition.artifact_id=accepted_artifact.id AND disposition.disposition='SUPERSEDED')
   OR (SELECT count(*) FROM record_artifact_links WHERE consumer_id=attempt.plan_artifact_id AND role='ACCEPTED_IDEA')<>1
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=attempt.plan_artifact_id AND producer_id=accepted_artifact.id AND role='ACCEPTED_IDEA')
   OR command.kind NOT IN ('START_MARKET_RESEARCH','COMMIT_MARKET_RESEARCH_OUTCOME','DECIDE_MATERIAL_PIVOT','START_INCONCLUSIVE_SUPPLEMENT','RETURN_FOR_TARGETED_RESEARCH')
   OR (command.kind='START_MARKET_RESEARCH' AND (command.result_type<>'RESEARCH_ATTEMPT' OR command.result_id IS DISTINCT FROM NEW.research_attempt_id))
  THEN RAISE EXCEPTION 'invalid idea-to-research transition'; END IF;
 ELSE
  SELECT * INTO committed FROM record_verdicts WHERE id=NEW.verdict_id AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id AND attempt_id=NEW.research_attempt_id;
  IF committed.id IS NULL THEN RAISE EXCEPTION 'invalid committed verdict transition'; END IF;
  expected_state := CASE committed.verdict WHEN 'PROCEED_TO_OFFER' THEN 'PROCEED_TO_OFFER' WHEN 'REFINE_SAME_IDEA' THEN 'RETURN_FOR_REFINEMENT' WHEN 'MATERIAL_PIVOT_RECOMMENDED' THEN 'WAITING_FOR_PIVOT_APPROVAL' WHEN 'KILL_IDEA' THEN 'KILLED' WHEN 'INCONCLUSIVE' THEN 'INCONCLUSIVE_REVIEW' END;
  IF NEW.ordinal=2 AND (NEW.to_state IS DISTINCT FROM expected_state OR command.kind<>'COMMIT_MARKET_RESEARCH_OUTCOME' OR command.result_id IS DISTINCT FROM committed.id)
  THEN RAISE EXCEPTION 'verdict and cycle state disagree'; END IF;
  IF NEW.ordinal=3 AND NOT EXISTS(SELECT 1 FROM record_returns r WHERE r.verdict_id=committed.id AND r.experiment_id=NEW.experiment_id AND r.from_cycle_id=NEW.cycle_id AND ((NEW.from_state='WAITING_FOR_PIVOT_APPROVAL' AND r.kind='MATERIAL_PIVOT' AND command.kind='DECIDE_MATERIAL_PIVOT' AND EXISTS(SELECT 1 FROM record_pivot_decisions p WHERE p.verdict_id=committed.id AND p.cycle_id=r.to_cycle_id AND p.decision='APPROVED')) OR (NEW.from_state='INCONCLUSIVE_REVIEW' AND r.kind='INCONCLUSIVE_SUPPLEMENT' AND command.kind='START_INCONCLUSIVE_SUPPLEMENT')))
  THEN RAISE EXCEPTION 'return transition requires exact accepted continuation'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_experiment_strategy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE paused BOOLEAN; pinned UUID; selected UUID;
BEGIN
 SELECT kind='PAUSE' INTO paused FROM record_learning_review_controls
  WHERE registry_scope AND kind IN ('PAUSE','RESUME') ORDER BY event_ordinal DESC LIMIT 1;
 SELECT CASE WHEN kind='PIN' THEN package_id END INTO pinned FROM record_learning_review_controls
  WHERE registry_scope AND kind IN ('PIN','UNPIN') ORDER BY event_ordinal DESC LIMIT 1;
 SELECT package_id INTO selected FROM record_learning_review_controls
  WHERE registry_scope AND kind IN ('BOOTSTRAP_PACKAGE','PROMOTE_PACKAGE','ASSESSED_ROLLBACK','FORCED_ROLLBACK')
  ORDER BY event_ordinal DESC LIMIT 1;
 IF coalesce(paused,false) OR NEW.package_id<>coalesce(pinned,selected)
  OR EXISTS(SELECT 1 FROM gov_calls WHERE experiment_id=NEW.experiment_id)
 THEN RAISE EXCEPTION 'experiment strategy selection is not currently authorized'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a record_artifacts; c record_cycles; parent_idea record_artifacts;
        decision record_pivot_decisions; proof gov_evidence; retained gov_retained;
        call gov_calls; validation record_artifacts; recommendation record_artifacts;
        committed record_verdicts; attempt record_research_attempts; parent_cycle record_cycles;
BEGIN
 IF TG_OP='UPDATE' OR TG_OP='DELETE' THEN
  RAISE EXCEPTION 'immutable product record' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME<>'record_operator_profiles' AND to_jsonb(NEW)->>'experiment_id' IS NOT NULL THEN
  PERFORM 1 FROM gov_experiments WHERE id=(to_jsonb(NEW)->>'experiment_id')::uuid FOR UPDATE;
 END IF;
 IF TG_TABLE_NAME='record_operator_profiles' THEN
  NEW.content_hash:=encode(sha256(convert_to(NEW.capabilities::text || E'\n' || NEW.constraints::text, 'UTF8')), 'hex');
  IF jsonb_typeof(NEW.capabilities)<>'array' OR jsonb_array_length(NEW.capabilities)=0
     OR jsonb_typeof(NEW.constraints)<>'array' OR jsonb_array_length(NEW.constraints)=0
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.capabilities) x WHERE NOT record_nonempty_text(x))
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.constraints) x WHERE NOT record_nonempty_text(x))
     OR jsonb_array_length(NEW.capabilities)<>(SELECT count(DISTINCT x) FROM jsonb_array_elements(NEW.capabilities) x)
     OR jsonb_array_length(NEW.constraints)<>(SELECT count(DISTINCT x) FROM jsonb_array_elements(NEW.constraints) x)
  THEN RAISE EXCEPTION 'invalid operator profile'; END IF;
 ELSIF TG_TABLE_NAME='record_artifacts' THEN
  NEW.content_hash:=encode(sha256(convert_to(NEW.payload::text, 'UTF8')), 'hex');
  IF record_payload_valid(NEW.kind,NEW.payload) IS NOT TRUE THEN RAISE EXCEPTION 'invalid artifact payload'; END IF;
 ELSIF TG_TABLE_NAME='record_artifact_links' THEN
  IF record_lineage_closed(NEW.consumer_id,NEW.experiment_id)
  THEN RAISE EXCEPTION 'accepted artifact lineage is closed'; END IF;
 ELSIF TG_TABLE_NAME='record_source_refs' THEN
  IF record_lineage_closed(NEW.artifact_id,NEW.experiment_id)
  THEN RAISE EXCEPTION 'accepted artifact lineage is closed'; END IF;
  IF NEW.kind='GOVERNANCE_EVIDENCE' THEN
   SELECT * INTO proof FROM gov_evidence WHERE id=NEW.evidence_id;
   IF NOT FOUND OR (proof.call_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM gov_calls WHERE id=proof.call_id AND experiment_id=NEW.experiment_id))
   THEN RAISE EXCEPTION 'invalid evidence scope'; END IF;
  ELSE
   SELECT * INTO retained FROM gov_retained WHERE id=NEW.retained_id;
   SELECT * INTO call FROM gov_calls WHERE id=NEW.call_id;
   IF retained.id IS NULL OR call.id IS NULL OR retained.call_id IS DISTINCT FROM NEW.call_id OR retained.grant_id IS DISTINCT FROM NEW.grant_id
      OR retained.grant_version IS DISTINCT FROM NEW.grant_version OR retained.field IS DISTINCT FROM NEW.field
      OR retained.expires_at IS DISTINCT FROM NEW.expires_at OR call.experiment_id IS DISTINCT FROM NEW.experiment_id
   THEN RAISE EXCEPTION 'invalid retained source scope'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='record_cycles' THEN
  IF NEW.ordinal <> (SELECT count(*)+1 FROM record_cycles WHERE experiment_id=NEW.experiment_id)
  THEN RAISE EXCEPTION 'noncontiguous research cycle'; END IF;
  IF NEW.ordinal=1 THEN
   IF NEW.parent_cycle_id IS NOT NULL THEN RAISE EXCEPTION 'initial cycle cannot have a parent'; END IF;
  ELSE
   SELECT * INTO parent_cycle FROM record_cycles WHERE id=NEW.parent_cycle_id AND experiment_id=NEW.experiment_id;
   IF parent_cycle.id IS NULL OR parent_cycle.ordinal<>NEW.ordinal-1
      OR ROW(NEW.seed_artifact_id,NEW.seed_kind,NEW.seed_version,NEW.seed_hash)
         IS DISTINCT FROM ROW(parent_cycle.seed_artifact_id,parent_cycle.seed_kind,parent_cycle.seed_version,parent_cycle.seed_hash)
   THEN RAISE EXCEPTION 'research cycle must preserve original seed and exact parent'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='record_pivot_decisions' THEN
  SELECT * INTO a FROM record_artifacts WHERE id=NEW.artifact_id;
  SELECT * INTO c FROM record_cycles WHERE id=NEW.cycle_id;
  IF NEW.cycle_id IS DISTINCT FROM (SELECT id FROM record_cycles WHERE experiment_id=NEW.experiment_id ORDER BY ordinal DESC LIMIT 1) THEN RAISE EXCEPTION 'pivot requires current cycle'; END IF;
  IF a.payload->'material_pivot' IS DISTINCT FROM 'true'::jsonb OR record_operator_authorized(NEW.experiment_id,NEW.approved_by) IS NOT TRUE
  THEN RAISE EXCEPTION 'invalid material pivot approval'; END IF;
 ELSIF TG_TABLE_NAME='record_idea_acceptances' THEN
  SELECT * INTO a FROM record_artifacts WHERE id=NEW.artifact_id;
  SELECT * INTO c FROM record_cycles WHERE id=NEW.cycle_id;
  IF NEW.cycle_id IS DISTINCT FROM (SELECT id FROM record_cycles WHERE experiment_id=NEW.experiment_id ORDER BY ordinal DESC LIMIT 1) THEN RAISE EXCEPTION 'idea requires current cycle'; END IF;
  IF c.parent_cycle_id IS NOT NULL THEN
   SELECT prior_artifact.* INTO parent_idea FROM record_idea_acceptances prior
    JOIN record_artifacts prior_artifact ON prior_artifact.id=prior.artifact_id
    WHERE prior.cycle_id=c.parent_cycle_id;
   SELECT prior_verdict.* INTO committed FROM record_returns r
    JOIN record_verdicts prior_verdict ON prior_verdict.id=r.verdict_id
    WHERE r.to_cycle_id=NEW.cycle_id;
  END IF;
  IF c.parent_cycle_id IS NOT NULL AND parent_idea.id IS NULL THEN RAISE EXCEPTION 'missing parent accepted idea'; END IF;
  IF record_operator_authorized(NEW.experiment_id,NEW.accepted_by) IS NOT TRUE
  THEN RAISE EXCEPTION 'idea acceptance requires operator capability'; END IF;
  IF committed.verdict='MATERIAL_PIVOT_RECOMMENDED' AND parent_idea.payload->>'core_intent' IS NOT DISTINCT FROM a.payload->>'core_intent'
  THEN RAISE EXCEPTION 'material pivot must change core intent'; END IF;
  IF c.parent_cycle_id IS NOT NULL AND parent_idea.payload->>'core_intent' IS DISTINCT FROM a.payload->>'core_intent' THEN
   IF a.payload->'material_pivot'<>'true'::jsonb OR NEW.pivot_approval_id IS NULL THEN RAISE EXCEPTION 'material pivot requires approval'; END IF;
  ELSIF c.parent_cycle_id IS NOT NULL AND c.purpose NOT IN ('INCONCLUSIVE_SUPPLEMENT','OFFER_GAP_RETURN') AND (a.payload->'material_pivot'='true'::jsonb OR NEW.pivot_approval_id IS NOT NULL) THEN
   RAISE EXCEPTION 'invalid pivot classification';
  END IF;
  IF c.parent_cycle_id IS NULL AND a.payload->'material_pivot'='true'::jsonb AND NEW.pivot_approval_id IS NULL
  THEN RAISE EXCEPTION 'initial material pivot requires approval'; END IF;
  IF c.parent_cycle_id IS NULL AND a.payload->'material_pivot'='false'::jsonb AND NEW.pivot_approval_id IS NOT NULL
  THEN RAISE EXCEPTION 'invalid initial pivot classification'; END IF;
  IF c.purpose IN ('INCONCLUSIVE_SUPPLEMENT','OFFER_GAP_RETURN') AND a.id IS DISTINCT FROM parent_idea.id
  THEN RAISE EXCEPTION 'supplement must preserve exact accepted idea'; END IF;
  IF NEW.pivot_approval_id IS NOT NULL THEN
   SELECT * INTO decision FROM record_pivot_decisions WHERE id=NEW.pivot_approval_id;
   IF decision.cycle_id IS DISTINCT FROM NEW.cycle_id OR decision.artifact_id IS DISTINCT FROM NEW.artifact_id OR decision.approved_by IS DISTINCT FROM NEW.accepted_by
   THEN RAISE EXCEPTION 'invalid pivot approval binding'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='record_research_attempts' THEN
  IF NOT EXISTS(SELECT 1 FROM record_idea_acceptances WHERE cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id)
     OR EXISTS(SELECT 1 FROM record_verdicts WHERE cycle_id=NEW.cycle_id)
     OR NEW.cycle_id IS DISTINCT FROM (SELECT id FROM record_cycles WHERE experiment_id=NEW.experiment_id ORDER BY ordinal DESC LIMIT 1)
     OR NEW.ordinal <> (SELECT count(*)+1 FROM record_research_attempts WHERE cycle_id=NEW.cycle_id)
     OR (SELECT count(*) FROM record_artifact_links WHERE consumer_id=NEW.plan_artifact_id AND role='ACCEPTED_IDEA')<>1
     OR NOT EXISTS(SELECT 1 FROM record_artifact_links link JOIN record_idea_acceptances idea ON idea.artifact_id=link.producer_id
         WHERE link.consumer_id=NEW.plan_artifact_id AND link.role='ACCEPTED_IDEA' AND idea.cycle_id=NEW.cycle_id)
  THEN RAISE EXCEPTION 'research attempt requires current accepted idea and exact plan lineage'; END IF;
 ELSIF TG_TABLE_NAME='record_verdicts' THEN
  SELECT * INTO attempt FROM record_research_attempts WHERE id=NEW.attempt_id;
  IF attempt.id IS NULL
     OR NOT EXISTS(SELECT 1 FROM record_idea_acceptances WHERE cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id)
     OR NEW.cycle_id IS DISTINCT FROM (SELECT id FROM record_cycles WHERE experiment_id=NEW.experiment_id ORDER BY ordinal DESC LIMIT 1)
     OR attempt.ordinal IS DISTINCT FROM (SELECT max(ordinal) FROM record_research_attempts WHERE cycle_id=NEW.cycle_id)
     OR (SELECT count(*) FROM record_artifact_links WHERE consumer_id=NEW.report_artifact_id AND role='PLAN')<>1
     OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=NEW.report_artifact_id AND producer_id=attempt.plan_artifact_id AND role='PLAN')
     OR (SELECT count(*) FROM record_artifact_links WHERE consumer_id=NEW.recommendation_artifact_id AND role='REPORT')<>1
     OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=NEW.recommendation_artifact_id AND producer_id=NEW.report_artifact_id AND role='REPORT')
  THEN RAISE EXCEPTION 'verdict requires current attempt and exact report lineage'; END IF;
  SELECT * INTO recommendation FROM record_artifacts WHERE id=NEW.recommendation_artifact_id;
  IF recommendation.payload->>'recommendation' IS DISTINCT FROM NEW.verdict OR record_operator_authorized(NEW.experiment_id,NEW.committed_by) IS NOT TRUE
  THEN RAISE EXCEPTION 'verdict recommendation or operator mismatch'; END IF;
 ELSIF TG_TABLE_NAME='record_artifact_dispositions' THEN
  IF NEW.disposition IN ('VALIDATED','ACCEPTED') THEN
   SELECT * INTO validation FROM record_artifacts WHERE id=NEW.validation_artifact_id AND experiment_id=NEW.experiment_id;
   IF validation.kind IS DISTINCT FROM 'VALIDATION_RESULT' OR validation.payload->>'disposition' IS DISTINCT FROM 'PASS'
      OR (SELECT count(*) FROM record_artifact_links WHERE consumer_id=validation.id AND role='TARGET')<>1
      OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=validation.id AND role='TARGET'
          AND producer_id=NEW.artifact_id AND producer_kind=NEW.artifact_kind
          AND producer_version=NEW.artifact_version AND producer_hash=NEW.artifact_hash)
   THEN RAISE EXCEPTION 'passing validation required'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_idea_discovery_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE intent openai_run_intents; operation gov_operations;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'discovery history is immutable'; END IF;
 IF TG_OP='UPDATE' AND (OLD.state<>'RUNNING' OR NEW.state='RUNNING'
   OR (to_jsonb(OLD)-ARRAY['state','advice','output_hash','candidate_ids','finished_at'])
      IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','advice','output_hash','candidate_ids','finished_at']))
 THEN RAISE EXCEPTION 'discovery identity or terminal result is immutable'; END IF;
 SELECT * INTO operation FROM gov_operations WHERE id=NEW.operation_id AND experiment_id=NEW.experiment_id;
 IF operation.id IS NULL THEN RAISE EXCEPTION 'discovery scope mismatch'; END IF;
 IF NEW.state='SUCCEEDED' THEN
  SELECT * INTO intent FROM openai_run_intents WHERE idempotency_key=NEW.run_id
    AND experiment_id=NEW.experiment_id AND operation_id=NEW.operation_id
    AND outcome='SUCCEEDED' AND output_hash=NEW.output_hash;
  IF intent.idempotency_key IS NULL THEN RAISE EXCEPTION 'discovery output is not a governed run'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_idea_intent_review_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE refinement record_idea_refinements; source record_artifacts;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'intent review is immutable'; END IF;
 SELECT * INTO refinement FROM record_idea_refinements WHERE run_id=NEW.run_id
   AND experiment_id=NEW.experiment_id AND cycle_id=NEW.cycle_id
   AND seed_artifact_id=NEW.source_artifact_id AND output_hash=NEW.output_hash
   AND state='SUCCEEDED';
 SELECT * INTO source FROM record_artifacts WHERE id=NEW.source_artifact_id
   AND experiment_id=NEW.experiment_id AND kind IN ('IDEA_SEED','IDEA_CANDIDATE');
 IF refinement.run_id IS NULL OR source.id IS NULL
 THEN RAISE EXCEPTION 'intent review must bind exact successful output and source'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_idea_refinement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE intent openai_run_intents; cycle record_cycles; operation gov_operations;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'refinement history is immutable'; END IF;
 IF TG_OP='UPDATE' AND (OLD.state<>'RUNNING' OR NEW.state='RUNNING'
   OR (to_jsonb(OLD)-ARRAY['state','advice','output_hash','finished_at'])
      IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['state','advice','output_hash','finished_at']))
 THEN RAISE EXCEPTION 'refinement identity or terminal result is immutable'; END IF;
 SELECT * INTO cycle FROM record_cycles WHERE id=NEW.cycle_id AND experiment_id=NEW.experiment_id
   AND seed_artifact_id=NEW.seed_artifact_id AND purpose='INITIAL'
   AND idea_mode IN ('USER_SEEDED_REFINEMENT','SYSTEM_DISCOVERY');
 SELECT * INTO operation FROM gov_operations WHERE id=NEW.operation_id AND experiment_id=NEW.experiment_id;
 IF cycle.id IS NULL OR operation.id IS NULL THEN RAISE EXCEPTION 'refinement scope mismatch'; END IF;
 IF NEW.state='SUCCEEDED' THEN
  SELECT * INTO intent FROM openai_run_intents WHERE idempotency_key=NEW.run_id
    AND experiment_id=NEW.experiment_id AND operation_id=NEW.operation_id
    AND outcome='SUCCEEDED' AND output_hash=NEW.output_hash;
  IF intent.idempotency_key IS NULL THEN RAISE EXCEPTION 'refinement output is not a successful governed run'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_assessment_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a record_learning_regression_assessments; f integer; n integer;
BEGIN
 SELECT * INTO a FROM record_learning_regression_assessments WHERE id=NEW.id;
 IF a.subject_kind='OFFLINE' THEN
  SELECT count(*) INTO f FROM record_learning_failure_analyses WHERE comparison_id=a.comparison_id;
  SELECT count(*) INTO n FROM record_negative_learning_records WHERE comparison_id=a.comparison_id;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM record_live_regression_assessment_seals WHERE assessment_id=a.id) THEN RAISE EXCEPTION 'live assessment must be sealed'; END IF;
  SELECT count(*) INTO f FROM record_learning_failure_analyses WHERE live_assessment_id=a.id;
  SELECT count(*) INTO n FROM record_negative_learning_records WHERE live_assessment_id=a.id;
 END IF;
 IF a.disposition IN ('FAIL','INCONCLUSIVE','REJECTED') AND (f<>1 OR n<1) THEN RAISE EXCEPTION 'negative learning evaluation requires retained analysis'; END IF;
 IF a.disposition='PASS' AND (f<>0 OR n<>0) THEN RAISE EXCEPTION 'successful evaluation cannot retain negative result'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_candidate_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record_learning_proposals; path text;
BEGIN
 SELECT * INTO p FROM record_learning_proposals WHERE id=NEW.proposal_id;
 IF p.id IS NULL OR p.class NOT IN ('PROMPT_CHANGE','CONFIG_CHANGE','STRATEGY_CHANGE') THEN RAISE EXCEPTION 'candidate not allowed for proposal class'; END IF;
 FOR path IN SELECT value->>'path' FROM jsonb_array_elements(NEW.config_diff) LOOP
  IF path IS NULL OR path !~ '^/' OR path ~* '(authorization|compliance|commercial_policy|offer_acceptance|product_policy)' THEN RAISE EXCEPTION 'protected learning diff'; END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_comparison_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record_learning_proposals; c record_learning_candidate_versions;
BEGIN
 SELECT * INTO p FROM record_learning_proposals WHERE id=NEW.proposal_id;
 IF p.id IS NULL OR NEW.input_bundle_id<>p.input_bundle_id THEN RAISE EXCEPTION 'learning comparison lineage mismatch'; END IF;
 IF NEW.candidate_id IS NOT NULL THEN SELECT * INTO c FROM record_learning_candidate_versions WHERE id=NEW.candidate_id; IF c.id IS NULL OR c.proposal_id<>p.id THEN RAISE EXCEPTION 'learning candidate comparison mismatch'; END IF; END IF;
 IF (p.class IN ('PROMPT_CHANGE','CONFIG_CHANGE','STRATEGY_CHANGE')) <> (NEW.candidate_id IS NOT NULL) THEN RAISE EXCEPTION 'learning comparison candidate mismatch'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_engineering_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record_learning_proposals; g record_capability_gaps;
BEGIN
 SELECT * INTO p FROM record_learning_proposals WHERE id=NEW.proposal_id; SELECT * INTO g FROM record_capability_gaps WHERE id=NEW.gap_id;
 IF p.id IS NULL OR g.id IS NULL OR g.proposal_id<>p.id OR p.class<>'ENGINEERING_CAPABILITY_REQUEST' THEN RAISE EXCEPTION 'engineering capability request must be descriptive'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_input_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE b record_learning_input_bundles;
BEGIN
 SELECT * INTO b FROM record_learning_input_bundles WHERE id=NEW.bundle_id;
 IF b.id IS NULL THEN RAISE EXCEPTION 'missing learning input bundle'; END IF;
 IF TG_TABLE_NAME='record_learning_input_evidence' THEN
  IF NOT EXISTS(SELECT 1 FROM gov_evidence WHERE id=NEW.evidence_id AND call_id=NEW.call_id)
  THEN RAISE EXCEPTION 'learning evidence call mismatch'; END IF;
 END IF;
 IF TG_TABLE_NAME='record_learning_input_costs' THEN
  IF (NEW.kind='SETTLEMENT' AND NOT EXISTS(SELECT 1 FROM gov_settlements WHERE id=NEW.cost_id AND call_id=NEW.call_id))
    OR (NEW.kind='CASH_ENTRY' AND NOT EXISTS(SELECT 1 FROM gov_cash_entries WHERE id=NEW.cost_id AND call_id=NEW.call_id))
  THEN RAISE EXCEPTION 'learning cost kind or call mismatch'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_negative_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a record_learning_regression_assessments;
BEGIN
 IF TG_TABLE_NAME='record_learning_failure_analyses' AND NEW.rollback_decision_id IS NOT NULL THEN
  RETURN NEW;
 ELSIF TG_TABLE_NAME='record_learning_failure_analyses' AND NEW.live_assessment_id IS NOT NULL THEN
  SELECT * INTO a FROM record_learning_regression_assessments WHERE id=NEW.live_assessment_id;
 ELSIF TG_TABLE_NAME='record_negative_learning_records' AND NEW.live_assessment_id IS NOT NULL THEN
  SELECT * INTO a FROM record_learning_regression_assessments WHERE id=NEW.live_assessment_id;
 ELSE RETURN NEW; END IF;
 IF a.disposition='PASS' THEN
  IF TG_TABLE_NAME='record_learning_failure_analyses' THEN
   RAISE EXCEPTION 'successful assessment cannot gain negative lineage';
  ELSIF NEW.rollback_decision_id IS NULL THEN
   RAISE EXCEPTION 'successful assessment cannot gain negative lineage';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_proposal_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record_learning_proposals; n integer;
BEGIN
 SELECT * INTO p FROM record_learning_proposals WHERE id=NEW.id;
 SELECT count(*) INTO n FROM record_learning_candidate_versions WHERE proposal_id=NEW.id;
 IF (p.class IN ('PROMPT_CHANGE','CONFIG_CHANGE','STRATEGY_CHANGE') AND n<>1) OR (p.class NOT IN ('PROMPT_CHANGE','CONFIG_CHANGE','STRATEGY_CHANGE') AND n<>0) THEN RAISE EXCEPTION 'learning candidate class mismatch'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.record_learning_proposal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r record_learning_runs; b record_learning_input_bundles; s record_learning_scopes;
BEGIN
 SELECT * INTO r FROM record_learning_runs WHERE id=NEW.run_id; SELECT * INTO b FROM record_learning_input_bundles WHERE id=NEW.input_bundle_id; SELECT * INTO s FROM record_learning_scopes WHERE id=NEW.scope_id;
 IF r.id IS NULL OR b.run_id<>r.id OR s.run_id<>r.id THEN RAISE EXCEPTION 'learning proposal lineage mismatch'; END IF;
 IF (NEW.class='OFFER_OR_PRODUCT_CHANGE' AND s.target_subsystem<>'PRODUCT_REVIEW') OR (NEW.class='ENGINEERING_CAPABILITY_REQUEST' AND s.target_subsystem<>'ENGINEERING_REVIEW') OR (NEW.class IN ('PROMPT_CHANGE','CONFIG_CHANGE','STRATEGY_CHANGE') AND s.target_subsystem IN ('PRODUCT_REVIEW','ENGINEERING_REVIEW')) THEN RAISE EXCEPTION 'invalid learning target subsystem'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_live_assessment_observation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a record_learning_regression_assessments; o record_live_strategy_observations;
BEGIN
 IF EXISTS(SELECT 1 FROM record_live_regression_assessment_seals WHERE assessment_id=NEW.assessment_id)
 THEN RAISE EXCEPTION 'live assessment is sealed'; END IF;
 SELECT * INTO a FROM record_learning_regression_assessments WHERE id=NEW.assessment_id;
 SELECT * INTO o FROM record_live_strategy_observations WHERE id=NEW.observation_id;
 IF a.subject_kind<>'LIVE' OR o.package_id<>a.live_package_id THEN RAISE EXCEPTION 'live assessment observation mismatch'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_offer_acceptance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE package record_offer_packages; qualification record_offer_qualification_profiles; policy record_initial_outreach_policies;
BEGIN
 SELECT * INTO package FROM record_offer_packages WHERE id=NEW.offer_id;
 SELECT * INTO qualification FROM record_offer_qualification_profiles WHERE id=NEW.profile_id;
 SELECT * INTO policy FROM record_initial_outreach_policies WHERE id=NEW.policy_id;
 IF record_operator_authorized(NEW.experiment_id,NEW.accepted_by) IS NOT TRUE
  OR package.experiment_id IS DISTINCT FROM NEW.experiment_id
  OR qualification.offer_id IS DISTINCT FROM package.id OR policy.offer_id IS DISTINCT FROM package.id
  OR NEW.offer_artifact_id IS DISTINCT FROM package.artifact_id
  OR NEW.profile_artifact_id IS DISTINCT FROM qualification.artifact_id
  OR NEW.policy_artifact_id IS DISTINCT FROM policy.artifact_id
  OR (SELECT array_agg(field_path ORDER BY field_path)::text[] FROM record_offer_field_sources WHERE offer_id=package.id) IS DISTINCT FROM ARRAY['base_price','buyer','claims','credible_outcome','currency','customer_responsibilities','deliverables','disqualifiers','exclusions','ideal_fit','negotiation_variables','payment_terms','pilot_terms','positioning','prerequisites','problem','scope','solution_mechanism','target_customer','third_party_costs','timeline','validity']
  OR (SELECT array_agg(DISTINCT category ORDER BY category)::text[] FROM record_qualification_criteria WHERE profile_id=qualification.id) IS DISTINCT FROM ARRAY['BUYER_FIT','CONTACT_FIT','ECONOMIC_FIT','EVIDENCE_QUESTION','FATAL_DISQUALIFIER','OFFER_SPECIFIC_ASSESSMENT','PILOT_FIT','POSITIVE_SIGNAL','REQUIRED_FIT','TECHNICAL_FIT']
 THEN RAISE EXCEPTION 'incomplete accepted offer set'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_offer_calibration_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d record_calibration_decisions; base record_offer_packages;
BEGIN
 IF NEW.calibration_decision_id IS NULL THEN RETURN NEW; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 SELECT * INTO d FROM record_calibration_decisions WHERE id=NEW.calibration_decision_id;
 SELECT * INTO base FROM record_offer_packages WHERE id=d.base_offer_id;
 IF d.outcome IS DISTINCT FROM 'ACCEPT' OR d.experiment_id IS DISTINCT FROM NEW.experiment_id
 OR base.bundle_id IS DISTINCT FROM NEW.bundle_id
 OR d.base_offer_acceptance_id IS DISTINCT FROM (SELECT id FROM record_offer_acceptances WHERE experiment_id=NEW.experiment_id ORDER BY accepted_at DESC,id DESC LIMIT 1)
 OR EXISTS(SELECT 1 FROM record_calibration_fulfillments WHERE calibration_decision_id=d.id)
 OR EXISTS(SELECT 1 FROM record_qualification_cohorts WHERE experiment_id=NEW.experiment_id)
 THEN RAISE EXCEPTION 'calibration cannot bypass offer acceptance'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_offer_design_run_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE verdict record_verdicts; bundle record_offer_bundles; envelope record_commercial_envelopes; state record_cycle_states;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable offer design run'; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 SELECT * INTO verdict FROM record_verdicts WHERE id=NEW.verdict_id AND experiment_id=NEW.experiment_id;
 SELECT * INTO bundle FROM record_offer_bundles WHERE id=NEW.bundle_id AND experiment_id=NEW.experiment_id;
 SELECT * INTO envelope FROM record_commercial_envelopes WHERE id=NEW.envelope_id AND experiment_id=NEW.experiment_id;
 SELECT * INTO state FROM record_cycle_states WHERE cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id FOR UPDATE;
 IF verdict.id IS NULL OR verdict.verdict IS DISTINCT FROM 'PROCEED_TO_OFFER' OR verdict.cycle_id IS DISTINCT FROM NEW.cycle_id
  OR bundle.id IS NULL OR bundle.verdict_id IS DISTINCT FROM NEW.verdict_id OR envelope.id IS NULL OR envelope.bundle_id IS DISTINCT FROM NEW.bundle_id OR envelope.status IS DISTINCT FROM 'READY'
  OR state.cycle_id IS NULL OR state.state IS DISTINCT FROM 'PROCEED_TO_OFFER'
  OR NOT EXISTS(SELECT 1 FROM record_artifacts a WHERE a.id=envelope.artifact_id AND a.experiment_id=NEW.experiment_id AND a.kind='COMMERCIAL_DESIGN_ENVELOPE' AND a.version=envelope.artifact_version AND a.content_hash=envelope.artifact_hash)
  OR EXISTS(SELECT 1 FROM record_artifacts a JOIN record_artifacts later ON later.logical_id=a.logical_id AND later.version>a.version WHERE a.id=envelope.artifact_id)
  OR EXISTS(SELECT 1 FROM record_artifact_dispositions d WHERE d.artifact_id=envelope.artifact_id AND d.disposition='SUPERSEDED')
  OR NOT EXISTS(SELECT 1 FROM record_artifacts a WHERE a.id=NEW.prompt_artifact_id AND a.experiment_id=NEW.experiment_id AND a.kind='OUTREACH_PROMPT_CONFIGURATION' AND a.version=NEW.prompt_version AND a.content_hash=NEW.prompt_hash)
  OR NOT EXISTS(SELECT 1 FROM gov_configs c WHERE c.id=NEW.model_config_id AND c.workflow_id=NEW.model_config_workflow_id AND c.version=NEW.model_config_version)
 THEN RAISE EXCEPTION 'invalid offer design run lineage'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_offer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE artifact record_artifacts; proposal record_offer_proposals; envelope record_commercial_envelopes;
 bundle record_offer_bundles; profile record_operator_profiles; commercial jsonb; expected_cost numeric; expected_floor numeric;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable offer record'; END IF;
 IF TG_TABLE_NAME<>'record_qualification_criteria' THEN
  PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 END IF;
 IF TG_TABLE_NAME='record_offer_bundles' THEN
  SELECT * INTO artifact FROM record_artifacts WHERE id=NEW.artifact_id;
  IF artifact.kind<>'OFFER_DESIGN_INPUT_BUNDLE' OR artifact.payload->>'status'<>'FROZEN'
   OR NOT EXISTS(SELECT 1 FROM record_verdicts v JOIN record_idea_acceptances i ON i.cycle_id=v.cycle_id WHERE v.id=NEW.verdict_id AND v.experiment_id=NEW.experiment_id AND v.verdict='PROCEED_TO_OFFER' AND i.id=NEW.idea_acceptance_id AND i.artifact_id=NEW.idea_artifact_id AND v.report_artifact_id=NEW.report_artifact_id)
  THEN RAISE EXCEPTION 'invalid accepted offer bundle'; END IF;
 ELSIF TG_TABLE_NAME='record_commercial_envelopes' THEN
  SELECT * INTO bundle FROM record_offer_bundles WHERE id=NEW.bundle_id;
  SELECT * INTO profile FROM record_operator_profiles WHERE id=NEW.operator_profile_id AND version=NEW.operator_profile_version;
  commercial:=profile.commercial;
  IF bundle.experiment_id IS DISTINCT FROM NEW.experiment_id OR NOT EXISTS(SELECT 1 FROM record_offer_bundle_inputs WHERE bundle_id=NEW.bundle_id AND role='SCOPE_ESTIMATE' AND artifact_id=NEW.scope_artifact_id)
   OR NEW.currency IS DISTINCT FROM commercial->>'currency' OR NEW.service_hours<>(SELECT (payload->>'hours')::numeric FROM record_artifacts WHERE id=NEW.scope_artifact_id)
  THEN RAISE EXCEPTION 'invalid envelope inputs'; END IF;
  IF NEW.status='READY' THEN
   expected_cost:=ceil(NEW.service_hours*(commercial->>'hourly_cost')::numeric*100)/100;
   expected_floor:=greatest((commercial->>'minimum_project_price')::numeric,ceil(expected_cost/(1-(commercial->>'minimum_margin_rate')::numeric)*100)/100);
   IF NEW.service_hours>(profile.delivery->>'max_project_hours')::numeric OR (commercial->>'minimum_margin_rate')::numeric>=1 OR NEW.delivery_cost<>expected_cost OR NEW.minimum_price<>expected_floor THEN RAISE EXCEPTION 'invalid commercial envelope'; END IF;
  ELSIF NEW.status='DELIVERY_CAPACITY_EXCEEDED' THEN
   IF NEW.service_hours<=(profile.delivery->>'max_project_hours')::numeric THEN RAISE EXCEPTION 'invalid delivery classification'; END IF;
  ELSIF NEW.status='IMPOSSIBLE_ECONOMICS' THEN
   IF NEW.service_hours>(profile.delivery->>'max_project_hours')::numeric OR (commercial->>'minimum_margin_rate')::numeric<1 THEN RAISE EXCEPTION 'invalid economics classification'; END IF;
  ELSIF NEW.status='CURRENCY_MISMATCH' THEN
   IF NEW.service_hours>(profile.delivery->>'max_project_hours')::numeric OR (commercial->>'minimum_margin_rate')::numeric>=1
    OR NOT EXISTS(SELECT 1 FROM record_offer_bundle_inputs input JOIN record_artifacts price ON price.id=input.artifact_id WHERE input.bundle_id=NEW.bundle_id AND input.role='PRICE_OBSERVATION' AND price.payload->>'currency' IS DISTINCT FROM NEW.currency)
   THEN RAISE EXCEPTION 'invalid currency classification'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='record_offer_proposals' THEN
  SELECT * INTO envelope FROM record_commercial_envelopes WHERE id=NEW.envelope_id;
  SELECT * INTO artifact FROM record_artifacts WHERE id=NEW.artifact_id;
  IF envelope.status<>'READY' OR envelope.bundle_id IS DISTINCT FROM NEW.bundle_id
   OR artifact.payload->>'currency' IS DISTINCT FROM envelope.currency
   OR (artifact.payload->>'base_price')::numeric<envelope.minimum_price
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=NEW.artifact_id AND producer_id=(SELECT artifact_id FROM record_offer_bundles WHERE id=NEW.bundle_id) AND role='INPUT_BUNDLE')
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=NEW.artifact_id AND producer_id=envelope.artifact_id AND role='ENVELOPE')
  THEN RAISE EXCEPTION 'invalid offer proposal'; END IF;
 ELSIF TG_TABLE_NAME='record_offer_packages' THEN
  SELECT * INTO proposal FROM record_offer_proposals WHERE id=NEW.proposal_id;
  SELECT * INTO artifact FROM record_artifacts WHERE id=NEW.artifact_id;
  SELECT * INTO envelope FROM record_commercial_envelopes WHERE id=proposal.envelope_id;
  IF proposal.bundle_id IS DISTINCT FROM NEW.bundle_id OR proposal.envelope_id IS DISTINCT FROM NEW.envelope_id
   OR EXISTS(SELECT 1 FROM record_offer_proposal_invalidations WHERE proposal_id=NEW.proposal_id)
   OR artifact.payload IS DISTINCT FROM (SELECT payload FROM record_artifacts WHERE id=proposal.artifact_id)
   OR NEW.currency IS DISTINCT FROM envelope.currency OR NEW.base_price<envelope.minimum_price
  THEN RAISE EXCEPTION 'invalid offer package'; END IF;
 ELSIF TG_TABLE_NAME='record_offer_field_sources' THEN
  IF NOT EXISTS(SELECT 1 FROM record_offer_packages package WHERE package.id=NEW.offer_id AND package.bundle_id=NEW.bundle_id)
   OR (NEW.source_artifact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM record_offer_bundle_inputs input WHERE input.bundle_id=NEW.bundle_id AND input.role=NEW.source_role AND input.artifact_id=NEW.source_artifact_id AND input.artifact_kind=NEW.source_kind AND input.artifact_version=NEW.source_version AND input.artifact_hash=NEW.source_hash))
   OR (NEW.source_artifact_id IS NOT NULL AND record_offer_field_role_valid(NEW.field_path,NEW.source_role) IS NOT TRUE)
   OR (NEW.operator_constraint IS NOT NULL AND NEW.operator_constraint IS DISTINCT FROM CASE NEW.field_path WHEN 'currency' THEN 'CURRENCY' WHEN 'base_price' THEN 'MINIMUM_PRICE' WHEN 'payment_terms' THEN 'MINIMUM_DEPOSIT_RATE' END)
  THEN RAISE EXCEPTION 'offer field source outside bundle'; END IF;
 ELSIF TG_TABLE_NAME='record_offer_gap_briefs' THEN
  SELECT * INTO proposal FROM record_offer_proposals WHERE id=NEW.proposal_id;
  IF proposal.bundle_id IS DISTINCT FROM NEW.bundle_id
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=NEW.artifact_id AND producer_id=proposal.artifact_id AND role='ORIGINATING_PROPOSAL')
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links WHERE consumer_id=NEW.artifact_id AND producer_id=(SELECT artifact_id FROM record_offer_bundles WHERE id=NEW.bundle_id) AND role='OFFER_INPUT_BUNDLE')
  THEN RAISE EXCEPTION 'invalid offer gap lineage'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_org_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e record_org_evidence; snapshot jsonb; value text; namespace text; r record_org_reservations; source record_org_recipient_sources;
 b record_org_bindings; retained gov_retained; call gov_calls; operation gov_operations; config gov_configs; proof gov_evidence;
 effect record_org_effects; prior record_org_observations; actor uuid;
BEGIN
 PERFORM pg_advisory_xact_lock(730803);
 IF TG_TABLE_NAME='record_org_policy' THEN
  IF TG_OP='UPDATE' AND OLD.key_fingerprint IS NULL AND NEW.id=OLD.id AND NEW.owns_pgcrypto=OLD.owns_pgcrypto AND NEW.key_fingerprint=encode(sha256(convert_to(current_setting('alon.organization_key',true),'UTF8')),'hex') AND octet_length(convert_to(current_setting('alon.organization_key',true),'UTF8'))=32 THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'immutable identity key policy';
 END IF;
 PERFORM record_org_require_key();
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable organization record'; END IF;
 IF TG_TABLE_NAME='record_org_evidence' THEN
  SELECT * INTO retained FROM gov_retained WHERE id=NEW.retained_id;
  SELECT * INTO call FROM gov_calls WHERE id=NEW.call_id;
  snapshot:=record_org_snapshot(NEW.retained_id,NEW.value_index);
  IF ROW(retained.call_id,retained.grant_id,retained.grant_version,retained.expires_at,call.operation_id,call.experiment_id) IS DISTINCT FROM ROW(NEW.call_id,NEW.grant_id,NEW.grant_version,NEW.expires_at,NEW.operation_id,NEW.experiment_id)
   OR NEW.snapshot_hash IS DISTINCT FROM encode(sha256(convert_to(retained.values->>NEW.value_index,'UTF8')),'hex') OR NEW.observed_at>record_org_now()
  THEN RAISE EXCEPTION 'exact organization provenance required'; END IF;
 ELSIF TG_TABLE_NAME IN ('record_org_keys','record_org_locations') THEN
  SELECT * INTO e FROM record_org_evidence WHERE id=NEW.evidence_id;
  snapshot:=record_org_snapshot(e.retained_id,e.value_index);
  IF TG_TABLE_NAME='record_org_locations' THEN
   IF NEW.source_index>=jsonb_array_length(snapshot->'locations') THEN RAISE EXCEPTION 'invalid location evidence'; END IF;
  ELSE
   IF NEW.source_index=-1 AND NEW.kind='NAME' THEN value:=snapshot->>'canonical_name'; namespace:='global';
   ELSIF NEW.source_index=-1 AND NEW.kind='DOMAIN' THEN value:=snapshot->>'canonical_domain'; namespace:='global';
   ELSIF NEW.kind IN ('REGISTERED_ID','PROVIDER_ID','OFFICIAL_URL') THEN
    IF snapshot->'identifiers'->NEW.source_index->>'kind' IS DISTINCT FROM NEW.kind THEN RAISE EXCEPTION 'identifier kind mismatch'; END IF;
    value:=snapshot->'identifiers'->NEW.source_index->>'value'; namespace:=snapshot->'identifiers'->NEW.source_index->>'namespace';
   ELSE
    IF snapshot->'aliases'->NEW.source_index->>'kind' IS DISTINCT FROM NEW.kind THEN RAISE EXCEPTION 'alias kind mismatch'; END IF;
    value:=snapshot->'aliases'->NEW.source_index->>'value'; namespace:='global';
   END IF;
   IF NEW.namespace IS DISTINCT FROM namespace OR NEW.lookup_hash IS DISTINCT FROM record_org_lookup(value) OR (NEW.kind='REGISTERED_ID' AND namespace !~ '^[A-Z]{2}$') THEN RAISE EXCEPTION 'invalid identity lookup'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='record_org_bindings' THEN
  SELECT * INTO e FROM record_org_evidence WHERE id=NEW.evidence_id;
  IF e.experiment_id IS DISTINCT FROM NEW.experiment_id OR NOT EXISTS(SELECT 1 FROM supply_identities i WHERE i.id=NEW.identity_id AND i.experiment_id=NEW.experiment_id AND i.valid_until>record_org_now()) THEN RAISE EXCEPTION 'invalid provisional identity binding'; END IF;
  snapshot:=record_org_snapshot(e.retained_id,e.value_index);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'identifiers') ident WHERE ident->>'kind'='REGISTERED_ID' AND NOT EXISTS(SELECT 1 FROM record_org_keys k WHERE k.kind='REGISTERED_ID' AND k.namespace=ident->>'namespace' AND k.lookup_hash=record_org_lookup(ident->>'value') AND (record_org_canonical(k.organization_id)=record_org_canonical(NEW.organization_id) OR EXISTS(SELECT 1 FROM record_org_conflicts conflict WHERE conflict.organization_id=NEW.organization_id AND conflict.matched_id=k.organization_id AND conflict.evidence_id=NEW.evidence_id)))) THEN RAISE EXCEPTION 'registered identity claim missing'; END IF;
 ELSIF TG_TABLE_NAME='record_org_identity_decisions' THEN
  IF NOT EXISTS(SELECT 1 FROM record_operators WHERE id=NEW.acted_by AND status='ACTIVE' AND auth_subject IS NOT NULL)
   OR record_org_evidence_current(NEW.evidence_id) IS NOT TRUE
   OR NOT EXISTS(SELECT 1 FROM record_org_conflicts conflict WHERE conflict.id=NEW.conflict_id AND EXISTS(SELECT 1 FROM record_org_evidence ev WHERE ev.id=NEW.evidence_id AND ev.organization_id IN (conflict.organization_id,conflict.matched_id)) AND ((NEW.resolution='SAME_ORGANIZATION' AND record_org_canonical(conflict.organization_id)=record_org_canonical(conflict.matched_id)) OR (NEW.resolution='INDEPENDENT_BUSINESS' AND record_org_canonical(conflict.organization_id)<>record_org_canonical(conflict.matched_id))))
  THEN RAISE EXCEPTION 'supported operator identity resolution required'; END IF;
 ELSIF TG_TABLE_NAME='record_org_recipient_sources' THEN
  SELECT * INTO b FROM record_org_bindings WHERE id=NEW.binding_id;
  SELECT * INTO retained FROM gov_retained WHERE id=NEW.retained_id;
  IF (SELECT lookup_hash FROM record_org_recipients WHERE id=NEW.recipient_id) IS DISTINCT FROM record_org_email_lookup(NEW.retained_id,NEW.value_index)
   OR NOT EXISTS(SELECT 1 FROM supply_candidates c WHERE c.id=NEW.candidate_id AND c.identity_id=b.identity_id AND c.experiment_id=NEW.experiment_id)
   OR NOT EXISTS(SELECT 1 FROM supply_facts f WHERE f.id=NEW.source_fact_id AND f.identity_id=b.identity_id AND f.kind='SOURCE_EMAIL' AND f.contact_ref=f.id AND f.valid_until>record_org_now())
   OR NOT (EXISTS(SELECT 1 FROM contact_cases cc WHERE cc.candidate_id=NEW.candidate_id AND cc.source_fact_id=NEW.source_fact_id AND cc.brave_call_id=retained.call_id AND cc.presence='PRESENT' AND cc.valid_until>record_org_now()) OR EXISTS(SELECT 1 FROM contact_attempts ca WHERE ca.candidate_id=NEW.candidate_id AND ca.output_fact_id=NEW.source_fact_id AND ca.call_id=retained.call_id AND ca.outcome='FOUND' AND ca.valid_until>record_org_now()))
  THEN RAISE EXCEPTION 'exact supported contact source required'; END IF;
 ELSIF TG_TABLE_NAME='record_org_admissions' THEN
  SELECT * INTO b FROM record_org_bindings WHERE id=NEW.binding_id;
  IF record_org_block_reason(NEW.organization_id,NULL,NEW.experiment_id) IS NOT NULL OR record_org_evidence_current(b.evidence_id) IS NOT TRUE THEN RAISE EXCEPTION 'protected working candidate'; END IF;
 ELSIF TG_TABLE_NAME='record_org_reservations' THEN
  SELECT * INTO source FROM record_org_recipient_sources WHERE id=NEW.source_id;
  IF record_org_block_reason(NEW.organization_id,NEW.recipient_id,NEW.experiment_id) IS NOT NULL
   OR record_org_email_lookup(source.retained_id,source.value_index) IS DISTINCT FROM (SELECT lookup_hash FROM record_org_recipients WHERE id=NEW.recipient_id)
   OR NOT EXISTS(SELECT 1 FROM record_org_admissions a WHERE a.organization_id=NEW.organization_id AND a.experiment_id=NEW.experiment_id)
   OR EXISTS(SELECT 1 FROM record_org_reservations reserved_row WHERE record_org_reservation_live(reserved_row.id) AND (record_org_canonical(reserved_row.organization_id)=record_org_canonical(NEW.organization_id) OR reserved_row.recipient_id=NEW.recipient_id))
  THEN RAISE EXCEPTION 'organization or recipient reservation conflict'; END IF;
 ELSIF TG_TABLE_NAME='record_org_effects' THEN
  SELECT * INTO r FROM record_org_reservations WHERE id=NEW.reservation_id;
  SELECT * INTO call FROM gov_calls WHERE id=NEW.call_id FOR UPDATE;
  SELECT * INTO operation FROM gov_operations WHERE id=NEW.operation_id;
  SELECT * INTO config FROM gov_configs WHERE id=call.config_id;
  IF call.state IS DISTINCT FROM 'RESERVED' OR call.dispatch_at IS NOT NULL OR record_org_reservation_live(r.id) IS NOT TRUE
   OR operation.service IS DISTINCT FROM 'send-gateway' OR operation.agent_id IS NOT NULL OR config.capability IS DISTINCT FROM 'GMAIL_SEND'
   OR ROW(call.operation_id,call.experiment_id,r.experiment_id) IS DISTINCT FROM ROW(NEW.operation_id,NEW.experiment_id,NEW.experiment_id)
   OR NEW.recipient_lookup_hash IS DISTINCT FROM (SELECT lookup_hash FROM record_org_recipients WHERE id=r.recipient_id)
   OR record_org_block_reason(r.organization_id,r.recipient_id,r.experiment_id) IS NOT NULL
  THEN RAISE EXCEPTION 'invalid gateway effect binding'; END IF;
 ELSIF TG_TABLE_NAME='record_org_observations' THEN
  SELECT * INTO effect FROM record_org_effects WHERE id=NEW.effect_id;
  SELECT * INTO call FROM gov_calls WHERE id=NEW.call_id FOR UPDATE;
  SELECT * INTO proof FROM gov_evidence WHERE id=NEW.result_evidence_id;
  SELECT * INTO prior FROM record_org_observations WHERE effect_id=NEW.effect_id AND outcome='AMBIGUOUS';
  IF NEW.observed_at>record_org_now() OR EXISTS(SELECT 1 FROM record_org_releases WHERE reservation_id=NEW.reservation_id) OR EXISTS(SELECT 1 FROM record_org_observations WHERE effect_id=NEW.effect_id AND outcome IN ('CONFIRMED','NO_EFFECT')) THEN RAISE EXCEPTION 'terminal or invalid gateway observation'; END IF;
  IF NEW.outcome='AMBIGUOUS' THEN
   IF call.state IS DISTINCT FROM 'RECONCILING' OR call.dispatch_at IS NULL OR NEW.reconciles_id IS NOT NULL THEN RAISE EXCEPTION 'uncertain dispatched call required'; END IF;
  ELSIF NEW.outcome='CONFIRMED' THEN
   IF call.state IS DISTINCT FROM 'FINAL' OR call.result_metadata->>'status' IS DISTINCT FROM 'SUCCEEDED'
    OR call.result_metadata->>'capability' IS DISTINCT FROM 'GMAIL_SEND' OR call.result_metadata->>'external_request_id' IS DISTINCT FROM NEW.provider_request_id
    OR ROW(proof.call_id,proof.kind,proof.mode,proof.registered_by) IS DISTINCT FROM ROW(NEW.call_id,'PROVIDER_RESULT'::text,'TRUSTED_REFERENCE'::text,NEW.call_id)
    OR NEW.reconciles_id IS DISTINCT FROM prior.id
   THEN RAISE EXCEPTION 'positive correlated gateway evidence required'; END IF;
  ELSE
   IF call.state IS DISTINCT FROM 'RELEASED' OR call.dispatch_at IS NOT NULL OR NEW.reconciles_id IS NOT NULL OR prior.id IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM gov_settlements settlement WHERE settlement.call_id=NEW.call_id AND settlement.kind='PROVEN_UNUSED' AND settlement.evidence_id=NEW.result_evidence_id)
   THEN RAISE EXCEPTION 'proven unused effect required'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='record_org_releases' THEN
  SELECT * INTO r FROM record_org_reservations WHERE id=NEW.reservation_id;
  IF record_operator_authorized(r.experiment_id,NEW.released_by) IS NOT TRUE OR EXISTS(SELECT 1 FROM record_org_observations WHERE reservation_id=r.id AND outcome IN ('CONFIRMED','AMBIGUOUS')) THEN RAISE EXCEPTION 'unsafe reservation release'; END IF;
  SELECT * INTO effect FROM record_org_effects WHERE reservation_id=r.id;
  IF effect.id IS NOT NULL THEN
   SELECT * INTO call FROM gov_calls WHERE id=effect.call_id FOR UPDATE;
   IF call.state IS DISTINCT FROM 'RELEASED' OR call.dispatch_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM gov_settlements st WHERE st.call_id=call.id AND st.kind='PROVEN_UNUSED' AND st.evidence_id=NEW.evidence_id) THEN RAISE EXCEPTION 'effect cancellation proof required'; END IF;
  ELSIF NEW.evidence_id IS NOT NULL THEN RAISE EXCEPTION 'unrelated release evidence'; END IF;
 ELSIF TG_TABLE_NAME IN ('record_org_suppressions','record_org_merges') THEN
  IF NOT EXISTS(SELECT 1 FROM record_operators WHERE id=NEW.acted_by AND status='ACTIVE' AND auth_subject IS NOT NULL) THEN RAISE EXCEPTION 'active operator required'; END IF;
  IF TG_TABLE_NAME='record_org_merges' THEN
   IF record_org_canonical(NEW.surviving_id)=NEW.losing_id OR record_org_canonical(NEW.losing_id)<>NEW.losing_id OR record_org_canonical(NEW.surviving_id)<>NEW.surviving_id
    OR NOT EXISTS(SELECT 1 FROM record_org_evidence ev WHERE ev.id=NEW.evidence_id AND ev.organization_id IN (NEW.losing_id,NEW.surviving_id) AND record_org_evidence_current(ev.id))
    OR (SELECT count(*) FROM record_org_reservations reserved_row WHERE record_org_reservation_live(reserved_row.id) AND record_org_canonical(reserved_row.organization_id) IN (NEW.losing_id,NEW.surviving_id) AND NOT EXISTS(SELECT 1 FROM record_org_observations WHERE reservation_id=reserved_row.id AND outcome='CONFIRMED'))>1
   THEN RAISE EXCEPTION 'unsafe organization merge'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_org_require_key()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE k text;
BEGIN
 k:=current_setting('alon.organization_key',true);
 IF k IS NULL OR octet_length(convert_to(k,'UTF8'))<>32 OR NOT EXISTS(SELECT 1 FROM record_org_policy WHERE id=1 AND key_fingerprint=encode(sha256(convert_to(k,'UTF8')),'hex')) THEN RAISE EXCEPTION 'identity key policy mismatch'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.record_origin_return_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE artifact_row record_artifacts; parent record_cycles; root_cycle record_cycles; child record_cycles;
 verdict_row record_verdicts; idea_row record_idea_acceptances; selection_row record_candidate_selections;
 scope_id uuid; expected_verdict text; expected_purpose text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable product record'; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 IF TG_TABLE_NAME='record_candidate_selections' THEN
  SELECT * INTO artifact_row FROM record_artifacts WHERE id=NEW.artifact_id;
  IF record_operator_authorized(NEW.experiment_id,NEW.selected_by) IS NOT TRUE
    OR ROW(artifact_row.workflow_id,artifact_row.agent_id) IS DISTINCT FROM ROW(NEW.workflow_id,NEW.agent_id)
    OR NOT EXISTS(SELECT 1 FROM record_experiments e WHERE e.id=NEW.experiment_id AND e.operator_profile_id=NEW.profile_id AND e.operator_profile_version=NEW.profile_version)
    OR EXISTS(SELECT 1 FROM record_cycles WHERE experiment_id=NEW.experiment_id)
  THEN RAISE EXCEPTION 'invalid candidate selection'; END IF;
 ELSIF TG_TABLE_NAME='record_cycles' THEN
  IF record_operator_authorized(NEW.experiment_id,(SELECT profile.operator_id FROM record_experiments experiment JOIN record_operator_profiles profile ON profile.id=experiment.operator_profile_id AND profile.version=experiment.operator_profile_version WHERE experiment.id=NEW.experiment_id)) IS NOT TRUE
  THEN RAISE EXCEPTION 'inactive experiment owner'; END IF;
  IF NEW.ordinal=1 THEN
   IF NEW.purpose IS DISTINCT FROM 'INITIAL' OR NEW.episode_id IS DISTINCT FROM NEW.id THEN RAISE EXCEPTION 'invalid initial episode'; END IF;
   SELECT * INTO artifact_row FROM record_artifacts WHERE id=NEW.seed_artifact_id;
   IF NEW.idea_mode='SYSTEM_DISCOVERY' THEN
    SELECT * INTO selection_row FROM record_candidate_selections WHERE id=NEW.selection_id;
    IF ROW(selection_row.artifact_id,selection_row.artifact_kind,selection_row.artifact_version,selection_row.artifact_hash,selection_row.experiment_id)
      IS DISTINCT FROM ROW(NEW.seed_artifact_id,NEW.seed_kind,NEW.seed_version,NEW.seed_hash,NEW.experiment_id)
    THEN RAISE EXCEPTION 'exact selection required'; END IF;
   ELSIF artifact_row.payload->>'origin' IS DISTINCT FROM 'USER_SUPPLIED' OR EXISTS(SELECT 1 FROM record_candidate_selections WHERE experiment_id=NEW.experiment_id)
   THEN RAISE EXCEPTION 'original user seed required'; END IF;
  ELSE
   SELECT * INTO parent FROM record_cycles WHERE id=NEW.parent_cycle_id;
   IF ROW(NEW.idea_mode,NEW.selection_id,NEW.episode_id) IS DISTINCT FROM ROW(parent.idea_mode,parent.selection_id,parent.episode_id) OR NEW.purpose='INITIAL'
   THEN RAISE EXCEPTION 'immutable origin and episode required'; END IF;
  END IF;
 ELSIF TG_TABLE_NAME='record_returns' THEN
  SELECT * INTO verdict_row FROM record_verdicts WHERE id=NEW.verdict_id;
  SELECT * INTO parent FROM record_cycles WHERE id=NEW.from_cycle_id;
  SELECT * INTO child FROM record_cycles WHERE id=NEW.to_cycle_id;
  SELECT * INTO root_cycle FROM record_cycles WHERE experiment_id=NEW.experiment_id AND ordinal=1;
  SELECT * INTO idea_row FROM record_idea_acceptances WHERE cycle_id=NEW.from_cycle_id;
  expected_verdict:=CASE NEW.kind WHEN 'SAME_INTENT' THEN 'REFINE_SAME_IDEA' WHEN 'MATERIAL_PIVOT' THEN 'MATERIAL_PIVOT_RECOMMENDED' WHEN 'INCONCLUSIVE_SUPPLEMENT' THEN 'INCONCLUSIVE' WHEN 'OFFER_GAP' THEN 'PROCEED_TO_OFFER' END;
  expected_purpose:=CASE NEW.kind WHEN 'SAME_INTENT' THEN 'SAME_INTENT_RETURN' WHEN 'MATERIAL_PIVOT' THEN 'MATERIAL_PIVOT_RETURN' WHEN 'INCONCLUSIVE_SUPPLEMENT' THEN 'INCONCLUSIVE_SUPPLEMENT' WHEN 'OFFER_GAP' THEN 'OFFER_GAP_RETURN' END;
  scope_id:=CASE NEW.kind WHEN 'SAME_INTENT' THEN CASE WHEN parent.idea_mode='USER_SEEDED_REFINEMENT' THEN parent.seed_artifact_id ELSE (SELECT artifact_id FROM record_idea_acceptances WHERE cycle_id=root_cycle.id) END WHEN 'OFFER_GAP' THEN idea_row.artifact_id ELSE parent.episode_id END;
  IF verdict_row.id IS NULL OR child.id IS NULL OR parent.id IS NULL OR idea_row.id IS NULL OR expected_verdict IS NULL
   OR verdict_row.cycle_id IS DISTINCT FROM parent.id OR verdict_row.verdict IS DISTINCT FROM expected_verdict
   OR child.parent_cycle_id IS DISTINCT FROM parent.id OR child.ordinal<>parent.ordinal+1 OR child.purpose IS DISTINCT FROM expected_purpose
   OR child.id IS DISTINCT FROM (SELECT cycle_row.id FROM record_cycles cycle_row WHERE cycle_row.experiment_id=NEW.experiment_id ORDER BY cycle_row.ordinal DESC LIMIT 1)
   OR NEW.applicable_scope_id IS DISTINCT FROM scope_id OR NEW.idea_artifact_id IS DISTINCT FROM idea_row.artifact_id
   OR NEW.ordinal<>(SELECT count(*)+1 FROM record_returns return_row WHERE return_row.experiment_id=NEW.experiment_id AND return_row.kind=NEW.kind AND return_row.applicable_scope_id=scope_id)
  THEN RAISE EXCEPTION 'invalid scoped research return'; END IF;
  IF NEW.kind='OFFER_GAP' THEN
   IF NOT EXISTS(
      SELECT 1 FROM record_offer_bundles bundle_row
      JOIN record_offer_gap_briefs gap_row ON gap_row.bundle_id=bundle_row.id
      JOIN record_offer_proposals proposal_row ON proposal_row.id=gap_row.proposal_id AND proposal_row.bundle_id=bundle_row.id
      WHERE bundle_row.artifact_id=NEW.offer_input_bundle_id AND bundle_row.experiment_id=NEW.experiment_id
        AND gap_row.artifact_id=NEW.feedback_artifact_id AND bundle_row.verdict_id=NEW.verdict_id
    ) OR NOT EXISTS(SELECT 1 FROM record_artifact_links link_row WHERE link_row.consumer_id=NEW.feedback_artifact_id AND link_row.producer_id=NEW.offer_input_bundle_id AND link_row.role='OFFER_INPUT_BUNDLE')
      OR NOT EXISTS(SELECT 1 FROM record_artifact_links link_row WHERE link_row.consumer_id=NEW.feedback_artifact_id AND link_row.role='REPORT' AND link_row.producer_id=verdict_row.report_artifact_id)
      OR NOT EXISTS(SELECT 1 FROM record_artifact_links link_row WHERE link_row.consumer_id=NEW.feedback_artifact_id AND link_row.role='RECOMMENDATION' AND link_row.producer_id=verdict_row.recommendation_artifact_id)
      OR NOT EXISTS(SELECT 1 FROM record_artifact_links link_row WHERE link_row.consumer_id=NEW.feedback_artifact_id AND link_row.role='ACCEPTED_IDEA' AND link_row.producer_id=idea_row.artifact_id)
   THEN RAISE EXCEPTION 'accepted offer gap lineage required'; END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM record_artifact_dispositions disposition_row WHERE disposition_row.artifact_id=NEW.feedback_artifact_id AND disposition_row.disposition='ACCEPTED')
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links link_row WHERE link_row.consumer_id=NEW.feedback_artifact_id AND link_row.role='REPORT' AND link_row.producer_id=verdict_row.report_artifact_id)
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links link_row WHERE link_row.consumer_id=NEW.feedback_artifact_id AND link_row.role='RECOMMENDATION' AND link_row.producer_id=verdict_row.recommendation_artifact_id)
   OR NOT EXISTS(SELECT 1 FROM record_artifact_links link_row WHERE link_row.consumer_id=NEW.feedback_artifact_id AND link_row.role='ACCEPTED_IDEA' AND link_row.producer_id=idea_row.artifact_id)
  THEN RAISE EXCEPTION 'accepted exact return evidence required'; END IF;
 ELSIF TG_TABLE_NAME='record_artifacts' THEN
  IF record_operator_authorized(NEW.experiment_id,NEW.created_by) IS NOT TRUE THEN RAISE EXCEPTION 'inactive artifact owner'; END IF;
 ELSIF TG_TABLE_NAME='record_research_attempts' THEN
  IF record_operator_authorized(NEW.experiment_id,(SELECT profile.operator_id FROM record_experiments experiment JOIN record_operator_profiles profile ON profile.id=experiment.operator_profile_id AND profile.version=experiment.operator_profile_version WHERE experiment.id=NEW.experiment_id)) IS NOT TRUE THEN RAISE EXCEPTION 'inactive experiment owner'; END IF;
  SELECT * INTO child FROM record_cycles WHERE id=NEW.cycle_id;
  IF child.ordinal>1 AND NOT EXISTS(SELECT 1 FROM record_returns return_row JOIN record_artifact_links link_row ON link_row.producer_id=return_row.feedback_artifact_id AND link_row.consumer_id=NEW.plan_artifact_id AND link_row.role='RETURN_FEEDBACK' WHERE return_row.to_cycle_id=child.id)
  THEN RAISE EXCEPTION 'research plan requires exact return feedback'; END IF;
 ELSIF TG_TABLE_NAME='record_artifact_dispositions' THEN
  IF record_operator_authorized(NEW.experiment_id,NEW.decided_by) IS NOT TRUE THEN RAISE EXCEPTION 'inactive decision owner'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_outreach_claim_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE claim record_outreach_claims;
BEGIN
 SELECT * INTO claim FROM record_outreach_claims WHERE artifact_id=NEW.artifact_id AND ordinal=NEW.ordinal;
 IF claim.kind='FACTUAL' AND NOT EXISTS(SELECT 1 FROM record_outreach_claim_evidence e WHERE e.artifact_id=claim.artifact_id AND e.ordinal=claim.ordinal) THEN RAISE EXCEPTION 'factual claim evidence required'; END IF;
 IF claim.kind='COMMERCIAL' AND NOT EXISTS(SELECT 1 FROM record_outreach_claim_offer_fields f WHERE f.artifact_id=claim.artifact_id AND f.ordinal=claim.ordinal) THEN RAISE EXCEPTION 'commercial claim offer field required'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.record_outreach_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target uuid:=COALESCE(to_jsonb(NEW)->>'context_id',to_jsonb(NEW)->>'id')::uuid; dossier uuid; expected integer; actual integer;
BEGIN
 SELECT dossier_id INTO dossier FROM record_outreach_contexts WHERE id=target;
 IF dossier IS NOT NULL THEN
  SELECT count(*) INTO expected FROM record_qualification_evidence WHERE dossier_id=dossier;
  SELECT count(*) INTO actual FROM record_outreach_coverage WHERE context_id=target;
  IF actual<>expected THEN RAISE EXCEPTION 'complete outreach evidence coverage required'; END IF;
  IF EXISTS(SELECT 1 FROM record_outreach_contexts c WHERE c.id=target AND c.recipient_mode<>'GENERAL_BUSINESS_INBOX' AND NOT EXISTS(SELECT 1 FROM record_outreach_coverage x WHERE x.context_id=c.id AND x.evidence_id=c.recipient_label_evidence_id AND x.disposition='USED')) THEN RAISE EXCEPTION 'recipient label requires used evidence'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.record_outreach_offer_field_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM record_outreach_contexts c WHERE c.id=NEW.context_id AND c.offer_id=NEW.offer_id) THEN
  RAISE EXCEPTION 'commercial claim requires exact context offer field';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_outreach_used_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM record_outreach_coverage c WHERE c.context_id=NEW.context_id AND c.evidence_id=NEW.evidence_id AND c.disposition='USED') THEN
  RAISE EXCEPTION 'only used outreach evidence may be referenced';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_qualification_exact_cohort()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target uuid:=COALESCE(to_jsonb(NEW)->>'cohort_id',to_jsonb(NEW)->>'id')::uuid;
BEGIN
 IF (SELECT count(*) FROM record_qualification_cohort_members WHERE cohort_id=target)<>50 THEN RAISE EXCEPTION 'cohort must contain exactly 50 members'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.record_qualification_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d record_qualification_dossiers; m record_qualification_matrices; decision record_qualification_decisions; cohort record_qualification_cohorts; acceptance record_offer_acceptances; result_count integer; criterion_count integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable qualification record'; END IF;
 IF TG_TABLE_NAME='record_qualification_dossiers' THEN
  SELECT * INTO acceptance FROM record_offer_acceptances WHERE id=NEW.offer_acceptance_id;
  IF ROW(acceptance.experiment_id,acceptance.offer_id,acceptance.profile_id,acceptance.policy_id) IS DISTINCT FROM ROW(NEW.experiment_id,NEW.offer_id,NEW.profile_id,NEW.policy_id)
   OR NOT EXISTS(SELECT 1 FROM supply_candidates c JOIN record_org_bindings b ON b.identity_id=c.identity_id AND b.id=NEW.binding_id JOIN record_org_admissions a ON a.binding_id=b.id AND a.id=NEW.admission_id JOIN record_org_recipient_sources r ON r.binding_id=b.id AND r.candidate_id=c.id AND r.id=NEW.recipient_source_id WHERE c.id=NEW.candidate_id AND c.experiment_id=NEW.experiment_id AND b.organization_id=NEW.organization_id AND r.recipient_id=NEW.recipient_id)
  THEN RAISE EXCEPTION 'exact dossier lineage required'; END IF;
 ELSIF TG_TABLE_NAME='record_qualification_matrices' THEN
  SELECT * INTO d FROM record_qualification_dossiers WHERE id=NEW.dossier_id;
  IF ROW(d.experiment_id,d.candidate_id,d.organization_id,d.recipient_id,d.recipient_source_id,d.offer_acceptance_id,d.offer_id,d.profile_id,d.policy_id) IS DISTINCT FROM ROW(NEW.experiment_id,NEW.candidate_id,NEW.organization_id,NEW.recipient_id,NEW.recipient_source_id,NEW.offer_acceptance_id,NEW.offer_id,NEW.profile_id,NEW.policy_id) THEN RAISE EXCEPTION 'exact matrix lineage required'; END IF;
 ELSIF TG_TABLE_NAME='record_qualification_decisions' THEN
  SELECT * INTO m FROM record_qualification_matrices WHERE id=NEW.matrix_id;
  SELECT count(*) INTO result_count FROM record_qualification_criterion_results r WHERE r.matrix_id=NEW.matrix_id AND EXISTS(SELECT 1 FROM record_qualification_result_evidence e WHERE e.matrix_id=r.matrix_id AND e.criterion_code=r.criterion_code);
  SELECT count(*) INTO criterion_count FROM record_qualification_criteria WHERE profile_id=NEW.profile_id;
  IF ROW(m.experiment_id,m.dossier_id,m.candidate_id,m.organization_id,m.recipient_id,m.recipient_source_id,m.offer_acceptance_id,m.offer_id,m.profile_id,m.policy_id) IS DISTINCT FROM ROW(NEW.experiment_id,NEW.dossier_id,NEW.candidate_id,NEW.organization_id,NEW.recipient_id,NEW.recipient_source_id,NEW.offer_acceptance_id,NEW.offer_id,NEW.profile_id,NEW.policy_id)
   OR ((EXISTS(SELECT 1 FROM record_readiness_research_plans p WHERE p.candidate_id=NEW.candidate_id) OR EXISTS(SELECT 1 FROM record_readiness_contactability_decisions contact WHERE contact.candidate_id=NEW.candidate_id)) AND EXISTS(
    SELECT 1 FROM record_qualification_evidence e WHERE e.dossier_id=NEW.dossier_id AND NOT EXISTS(
     SELECT 1 FROM record_readiness_evidence_links l
     JOIN record_readiness_research_runs r ON r.id=l.run_id
     JOIN record_readiness_research_plans p ON p.id=r.plan_id
     LEFT JOIN record_readiness_provider_results pr ON pr.id=r.provider_result_id
     LEFT JOIN gov_retained retained ON retained.id=pr.retained_id
     WHERE l.dossier_evidence_id=e.id AND p.candidate_id=NEW.candidate_id AND p.offer_acceptance_id=NEW.offer_acceptance_id
     AND (r.independent_source_id IS NOT NULL OR (pr.valid_until>NEW.decided_at AND retained.id IS NOT NULL AND record_org_source_current(retained.id,retained.field)))
    )))
   OR result_count<>criterion_count
   OR NEW.offer_acceptance_id IS DISTINCT FROM (SELECT id FROM record_offer_acceptances WHERE experiment_id=NEW.experiment_id ORDER BY accepted_at DESC,id DESC LIMIT 1)
   OR (NEW.outcome IN ('QUALIFIED_CONTACTABLE','PILOT_FIT_CONTACTABLE') AND EXISTS(SELECT 1 FROM record_qualification_criterion_results r JOIN record_qualification_criteria c ON c.profile_id=r.profile_id AND c.code=r.criterion_code WHERE r.matrix_id=NEW.matrix_id AND ((c.rule_kind='HARD_GATE' AND r.status<>'SATISFIED') OR (c.rule_kind='FATAL_DISQUALIFIER' AND r.status<>'NOT_SATISFIED'))))
   OR (NEW.outcome='PILOT_FIT_CONTACTABLE' AND NOT EXISTS(SELECT 1 FROM record_qualification_criterion_results r JOIN record_qualification_criteria c ON c.profile_id=r.profile_id AND c.code=r.criterion_code WHERE r.matrix_id=NEW.matrix_id AND c.category='PILOT_FIT' AND r.status='SATISFIED'))
   OR NOT EXISTS(SELECT 1 FROM supply_facts f JOIN supply_candidates c ON c.identity_id=f.identity_id AND c.experiment_id=f.experiment_id JOIN supply_plans p ON p.experiment_id=c.experiment_id WHERE c.id=NEW.candidate_id AND c.deep_started AND f.id=NEW.proposal_fact_id AND f.experiment_id=NEW.experiment_id AND f.observed_at<=NEW.decided_at AND f.valid_until>NEW.decided_at AND f.policy_ref::text=p.initial_plan->>'qualification_rule_id' AND ((NEW.outcome IN ('QUALIFIED_CONTACTABLE','PILOT_FIT_CONTACTABLE') AND f.kind='QUALIFIED') OR (NEW.outcome NOT IN ('QUALIFIED_CONTACTABLE','PILOT_FIT_CONTACTABLE') AND f.kind IN ('REJECTED_FIT','REJECTED_EVIDENCE'))))
  THEN RAISE EXCEPTION 'complete authoritative qualification required'; END IF;
 ELSIF TG_TABLE_NAME='record_qualification_cohorts' THEN
  SELECT * INTO acceptance FROM record_offer_acceptances WHERE id=NEW.offer_acceptance_id;
  IF ROW(acceptance.experiment_id,acceptance.offer_id,acceptance.profile_id,acceptance.policy_id) IS DISTINCT FROM ROW(NEW.experiment_id,NEW.offer_id,NEW.profile_id,NEW.policy_id)
   OR NEW.offer_acceptance_id IS DISTINCT FROM (SELECT id FROM record_offer_acceptances WHERE experiment_id=NEW.experiment_id ORDER BY accepted_at DESC,id DESC LIMIT 1)
  THEN RAISE EXCEPTION 'exact cohort offer required'; END IF;
 ELSIF TG_TABLE_NAME='record_qualification_cohort_members' THEN
  SELECT * INTO decision FROM record_qualification_decisions WHERE id=NEW.decision_id;
  SELECT * INTO cohort FROM record_qualification_cohorts WHERE id=NEW.cohort_id;
  IF decision.outcome NOT IN ('QUALIFIED_CONTACTABLE','PILOT_FIT_CONTACTABLE') OR decision.valid_until<=record_org_now()
   OR ROW(decision.experiment_id,decision.candidate_id,decision.organization_id,decision.recipient_id,decision.recipient_source_id) IS DISTINCT FROM ROW(NEW.experiment_id,NEW.candidate_id,NEW.organization_id,NEW.recipient_id,NEW.recipient_source_id)
   OR ROW(decision.experiment_id,decision.offer_acceptance_id,decision.offer_id,decision.profile_id,decision.policy_id) IS DISTINCT FROM ROW(cohort.experiment_id,cohort.offer_acceptance_id,cohort.offer_id,cohort.profile_id,cohort.policy_id)
   OR NOT EXISTS(SELECT 1 FROM record_org_reservations r WHERE r.id=NEW.reservation_id AND ROW(r.experiment_id,r.organization_id,r.recipient_id,r.source_id)=ROW(NEW.experiment_id,NEW.organization_id,NEW.recipient_id,NEW.recipient_source_id))
  THEN RAISE EXCEPTION 'invalid cohort member'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_readiness_cohort_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM record_calibration_decisions d WHERE d.experiment_id=NEW.experiment_id AND d.outcome='ACCEPT' AND NOT EXISTS(SELECT 1 FROM record_calibration_fulfillments f WHERE f.calibration_decision_id=d.id)) THEN
  RAISE EXCEPTION 'accepted calibration awaits fulfillment';
 END IF;
 IF TG_TABLE_NAME='record_qualification_cohort_members' THEN
 IF NOT EXISTS(
  SELECT 1 FROM record_current_supply_qualifications current
  JOIN record_qualification_decisions d ON d.proposal_fact_id=current.fact_id
  WHERE d.id=NEW.decision_id AND current.outcome='QUALIFIED'
 ) THEN RAISE EXCEPTION 'cohort requires current readiness'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_readiness_contact_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE candidate supply_candidates; contact supply_contacts; source record_org_recipient_sources; binding record_org_bindings;
BEGIN
 SELECT * INTO candidate FROM supply_candidates WHERE id=NEW.candidate_id;
 SELECT * INTO contact FROM supply_contacts WHERE candidate_id=NEW.candidate_id;
 IF candidate.id IS NULL OR contact.candidate_id IS NULL OR candidate.experiment_id<>NEW.experiment_id
    OR NEW.valid_until>contact.valid_until THEN RAISE EXCEPTION 'invalid contactability lineage'; END IF;
 IF NEW.provider_result_id IS NULL OR NOT EXISTS(
  SELECT 1 FROM record_readiness_provider_results pr WHERE pr.id=NEW.provider_result_id AND pr.candidate_id=NEW.candidate_id
  AND (EXISTS(SELECT 1 FROM contact_cases cc WHERE cc.candidate_id=NEW.candidate_id AND cc.brave_call_id=pr.call_id)
   OR EXISTS(SELECT 1 FROM contact_attempts a WHERE a.candidate_id=NEW.candidate_id AND a.call_id=pr.call_id AND a.output_fact_id IN (contact.source_id,contact.verification_id)))
 ) THEN RAISE EXCEPTION 'missing governed contact receipt'; END IF;
 IF contact.verification_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM contact_attempts a JOIN contact_operations o ON o.operation_id=a.operation_id
  WHERE a.candidate_id=NEW.candidate_id AND a.output_fact_id=contact.verification_id
  AND o.source_fact_id=contact.source_id AND o.capability='HUNTER_EMAIL_VERIFICATION'
  AND ((NEW.outcome='SUPPORTED_CONTACT_ADDRESS' AND a.outcome='VALID')
   OR (NEW.outcome='EMAIL_NOT_FOUND' AND a.outcome IN ('INVALID','ACCEPT_ALL','UNKNOWN')))
 ) THEN RAISE EXCEPTION 'missing governed verification'; END IF;
 IF NEW.outcome='SUPPORTED_CONTACT_ADDRESS' THEN
  SELECT * INTO source FROM record_org_recipient_sources WHERE id=NEW.recipient_source_id;
  IF source.id IS NULL OR source.experiment_id<>NEW.experiment_id OR source.candidate_id<>NEW.candidate_id
     OR source.organization_id<>NEW.organization_id OR source.recipient_id<>NEW.recipient_id
     OR source.source_fact_id<>NEW.source_fact_id OR contact.outcome<>'SUPPORTED'
     OR contact.source_id<>NEW.source_fact_id OR contact.verification_id IS DISTINCT FROM NEW.verification_fact_id
  THEN RAISE EXCEPTION 'invalid supported contactability'; END IF;
ELSEIF contact.outcome NOT IN ('EMAIL_NOT_FOUND','VERIFICATION_REJECTED') THEN
  RAISE EXCEPTION 'invalid no-email contactability';
 ELSE
  SELECT * INTO binding FROM record_org_bindings WHERE experiment_id=NEW.experiment_id AND identity_id=candidate.identity_id;
  IF binding.id IS NULL OR binding.organization_id<>NEW.organization_id THEN RAISE EXCEPTION 'missing no-email organization'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_readiness_evidence_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE run record_readiness_research_runs; plan record_readiness_research_plans; dossier record_qualification_dossiers; evidence record_qualification_evidence;
BEGIN
 SELECT * INTO run FROM record_readiness_research_runs WHERE id=NEW.run_id;
 SELECT * INTO dossier FROM record_qualification_dossiers WHERE id=NEW.dossier_id;
 SELECT * INTO evidence FROM record_qualification_evidence WHERE id=NEW.dossier_evidence_id;
 IF run.id IS NULL OR dossier.id IS NULL OR evidence.id IS NULL OR run.experiment_id<>NEW.experiment_id
    OR dossier.experiment_id<>NEW.experiment_id OR evidence.dossier_id<>dossier.id OR dossier.candidate_id<>run.candidate_id THEN RAISE EXCEPTION 'invalid research evidence lineage'; END IF;
 SELECT * INTO plan FROM record_readiness_research_plans WHERE id=run.plan_id;
 IF plan.offer_acceptance_id<>dossier.offer_acceptance_id THEN RAISE EXCEPTION 'stale research evidence offer'; END IF;
 IF run.provider_result_id IS NOT NULL AND evidence.source_ref<>('provider-result:'||run.provider_result_id::text) THEN RAISE EXCEPTION 'provider evidence provenance mismatch'; END IF;
 IF run.independent_source_id IS NOT NULL AND evidence.source_ref<>('independent-source:'||run.independent_source_id::text) THEN RAISE EXCEPTION 'independent evidence provenance mismatch'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_readiness_outreach_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target uuid; exp uuid;
BEGIN
 IF TG_TABLE_NAME='record_outreach_contexts' THEN target:=NEW.decision_id;
 ELSE SELECT c.decision_id INTO target FROM record_outreach_contexts c JOIN record_outreach_drafts d ON d.context_id=c.id WHERE d.artifact_id=NEW.draft_artifact_id;
 END IF;
 SELECT experiment_id INTO exp FROM record_qualification_decisions WHERE id=target;
 PERFORM 1 FROM gov_experiments WHERE id=exp FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM record_current_supply_qualifications current
 JOIN record_qualification_decisions d ON d.proposal_fact_id=current.fact_id
 WHERE d.id=target AND current.outcome='QUALIFIED') THEN
 RAISE EXCEPTION 'outreach requires current qualification'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_readiness_research_plan_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE candidate supply_candidates; source record_org_recipient_sources; acceptance record_offer_acceptances; artifact record_artifacts;
BEGIN
 SELECT * INTO candidate FROM supply_candidates WHERE id=NEW.candidate_id;
 SELECT * INTO source FROM record_org_recipient_sources WHERE id=NEW.recipient_source_id;
 SELECT * INTO acceptance FROM record_offer_acceptances WHERE id=NEW.offer_acceptance_id;
 SELECT * INTO artifact FROM record_artifacts WHERE id=NEW.artifact_id;
 IF candidate.id IS NULL OR source.id IS NULL OR acceptance.id IS NULL OR artifact.id IS NULL
    OR candidate.experiment_id<>NEW.experiment_id OR source.experiment_id<>NEW.experiment_id
    OR source.candidate_id<>NEW.candidate_id OR source.organization_id<>NEW.organization_id OR source.recipient_id<>NEW.recipient_id
    OR acceptance.experiment_id<>NEW.experiment_id OR acceptance.offer_id<>NEW.offer_id OR acceptance.profile_id<>NEW.profile_id OR acceptance.policy_id<>NEW.policy_id
    OR artifact.experiment_id<>NEW.experiment_id OR artifact.kind<>NEW.artifact_kind OR artifact.version<>NEW.artifact_version OR artifact.content_hash<>NEW.artifact_hash
 THEN RAISE EXCEPTION 'invalid research plan lineage'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_readiness_research_run_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE plan record_readiness_research_plans; result record_readiness_provider_results; source supply_references;
BEGIN
 SELECT * INTO plan FROM record_readiness_research_plans WHERE id=NEW.plan_id;
 IF plan.id IS NULL OR plan.experiment_id<>NEW.experiment_id OR plan.candidate_id<>NEW.candidate_id THEN RAISE EXCEPTION 'invalid research run plan'; END IF;
 IF NEW.provider_result_id IS NOT NULL THEN
  SELECT * INTO result FROM record_readiness_provider_results WHERE id=NEW.provider_result_id;
  IF result.id IS NULL OR result.experiment_id<>NEW.experiment_id OR result.candidate_id<>NEW.candidate_id OR result.retained_id IS NULL THEN RAISE EXCEPTION 'invalid provider research provenance'; END IF;
 ELSE
  SELECT * INTO source FROM supply_references WHERE id=NEW.independent_source_id;
  IF source.id IS NULL OR source.experiment_id<>NEW.experiment_id OR source.kind<>'INDEPENDENT_SOURCE' THEN RAISE EXCEPTION 'invalid independent research provenance'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_research_budget_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE account gov_budget_accounts;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable research cycle budget'; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 SELECT * INTO account FROM gov_budget_accounts WHERE id=NEW.budget_account_id;
 IF account.id IS NULL OR account.scope<>'WORKFLOW' OR account.experiment_id IS DISTINCT FROM NEW.experiment_id
  OR account.workflow_id IS DISTINCT FROM NEW.workflow_id OR account.frozen
  OR account.effective_at>NEW.created_at OR account.expires_at<=NEW.created_at
 THEN RAISE EXCEPTION 'invalid research workflow budget'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_research_decision_binding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prefix TEXT; c record_commands;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable research decision workflow binding'; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 IF TG_OP='INSERT' THEN
  prefix:=CASE NEW.operation_kind WHEN 'OUTCOME' THEN 'market-research-outcome' WHEN 'PIVOT_DECISION' THEN 'material-pivot-decision' WHEN 'INCONCLUSIVE_SUPPLEMENT' THEN 'inconclusive-supplement' END;
  IF NEW.dbos_workflow_id IS DISTINCT FROM prefix||':'||NEW.operation_id::text||':'||
    (CASE WHEN NEW.operation_kind='PIVOT_DECISION' THEN NEW.request_payload->>'decision_id'
          ELSE NEW.business_command_key::text END)
    OR NEW.delivery_state<>'PENDING' THEN RAISE EXCEPTION 'invalid research decision workflow identity'; END IF;
  IF (NEW.operation_kind='OUTCOME' AND NOT EXISTS(SELECT 1 FROM record_research_attempts WHERE id=NEW.operation_id AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id))
    OR (NEW.operation_kind<>'OUTCOME' AND NOT EXISTS(SELECT 1 FROM record_verdicts WHERE id=NEW.operation_id AND cycle_id=NEW.cycle_id AND experiment_id=NEW.experiment_id))
  THEN RAISE EXCEPTION 'invalid research decision workflow operation'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['command_id','result_id','failure_code','delivery_state','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['command_id','result_id','failure_code','delivery_state','updated_at'])
 THEN RAISE EXCEPTION 'immutable research decision workflow identity'; END IF;
 IF NOT ((OLD.delivery_state='PENDING' AND NEW.delivery_state IN ('STARTED','CANCELLED'))
   OR (OLD.delivery_state='STARTED' AND NEW.delivery_state IN ('BUSINESS_COMMITTED','CANCELLED','REJECTED'))
   OR (OLD.delivery_state='BUSINESS_COMMITTED' AND NEW.delivery_state='RECEIPT_DELIVERED')
   OR (OLD.delivery_state='RECEIPT_DELIVERED' AND NEW.delivery_state='RUNTIME_COMPLETED'))
 THEN RAISE EXCEPTION 'invalid research decision workflow delivery transition'; END IF;
 IF OLD.command_id IS NOT NULL AND (NEW.command_id,NEW.result_id) IS DISTINCT FROM (OLD.command_id,OLD.result_id)
 THEN RAISE EXCEPTION 'immutable research decision workflow receipt'; END IF;
 IF NEW.delivery_state='CANCELLED' AND EXISTS(SELECT 1 FROM record_commands WHERE command_key=NEW.business_command_key)
 THEN RAISE EXCEPTION 'committed research decision workflow cannot be cancelled'; END IF;
 IF NEW.command_id IS NOT NULL THEN
  SELECT * INTO c FROM record_commands WHERE id=NEW.command_id;
  IF c.id IS NULL OR c.command_key IS DISTINCT FROM NEW.business_command_key OR c.request_hash IS DISTINCT FROM NEW.request_hash
   OR c.experiment_id IS DISTINCT FROM NEW.experiment_id OR c.result_id IS DISTINCT FROM NEW.result_id
   OR c.kind IS DISTINCT FROM (CASE NEW.operation_kind WHEN 'OUTCOME' THEN 'COMMIT_MARKET_RESEARCH_OUTCOME' WHEN 'PIVOT_DECISION' THEN 'DECIDE_MATERIAL_PIVOT' WHEN 'INCONCLUSIVE_SUPPLEMENT' THEN 'START_INCONCLUSIVE_SUPPLEMENT' END)
  THEN RAISE EXCEPTION 'invalid research decision workflow receipt lineage'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_research_pivot_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record_cycles; a record_artifacts; v record_verdicts;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable pivot decision'; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 SELECT * INTO c FROM record_cycles WHERE id=NEW.cycle_id AND experiment_id=NEW.experiment_id;
 IF c.id IS NULL OR record_operator_authorized(NEW.experiment_id,NEW.approved_by) IS NOT TRUE
  OR NEW.cycle_id IS DISTINCT FROM (SELECT id FROM record_cycles WHERE experiment_id=NEW.experiment_id ORDER BY ordinal DESC LIMIT 1)
 THEN RAISE EXCEPTION 'pivot requires current cycle and authorized operator'; END IF;
 IF NEW.verdict_id IS NOT NULL THEN
  SELECT * INTO v FROM record_verdicts WHERE id=NEW.verdict_id AND experiment_id=NEW.experiment_id;
  IF v.id IS NULL OR v.verdict<>'MATERIAL_PIVOT_RECOMMENDED'
   OR (NEW.decision='DENIED' AND c.id IS DISTINCT FROM v.cycle_id)
   OR (NEW.decision='APPROVED' AND c.parent_cycle_id IS DISTINCT FROM v.cycle_id)
   OR NEW.decision_ordinal<>(SELECT count(*)+1 FROM record_pivot_decisions WHERE verdict_id=NEW.verdict_id)
   OR NOT EXISTS(SELECT 1 FROM record_cycle_states WHERE cycle_id=v.cycle_id AND state='WAITING_FOR_PIVOT_APPROVAL')
  THEN RAISE EXCEPTION 'invalid pivot verdict lineage or ordinal'; END IF;
 ELSE
  IF NEW.decision<>'APPROVED' OR NEW.decision_ordinal<>(SELECT count(*)+1 FROM record_pivot_decisions WHERE cycle_id=NEW.cycle_id AND verdict_id IS NULL)
  THEN RAISE EXCEPTION 'invalid legacy pivot approval'; END IF;
 END IF;
 IF NEW.decision='APPROVED' THEN
  SELECT * INTO a FROM record_artifacts WHERE id=NEW.artifact_id;
  IF a.payload->'material_pivot' IS DISTINCT FROM 'true'::jsonb
  THEN RAISE EXCEPTION 'invalid material pivot approval'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_research_return_block_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable research return block'; END IF;
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM record_verdicts v WHERE v.id=NEW.verdict_id AND v.cycle_id=NEW.cycle_id AND v.experiment_id=NEW.experiment_id
  AND ((v.verdict='REFINE_SAME_IDEA' AND NEW.return_kind='SAME_INTENT') OR (v.verdict='MATERIAL_PIVOT_RECOMMENDED' AND NEW.return_kind='MATERIAL_PIVOT') OR (v.verdict='INCONCLUSIVE' AND NEW.return_kind='INCONCLUSIVE_SUPPLEMENT')))
 THEN RAISE EXCEPTION 'invalid return block verdict lineage'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_strategy_agent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior record_strategy_agent_versions;
BEGIN
 IF NEW.configuration::text ~* '"(authorization|compliance|commercial_policy|offer_acceptance|product_policy)"[[:space:]]*:'
 THEN RAISE EXCEPTION 'invalid strategy agent configuration'; END IF;
 IF NEW.supersedes_id IS NULL AND NEW.version<>1 THEN RAISE EXCEPTION 'strategy version requires predecessor'; END IF;
 IF NEW.supersedes_id IS NOT NULL THEN SELECT * INTO prior FROM record_strategy_agent_versions WHERE id=NEW.supersedes_id;
  IF prior.id IS NULL OR prior.logical_id<>NEW.logical_id OR prior.version+1<>NEW.version OR prior.role<>NEW.role THEN RAISE EXCEPTION 'invalid strategy predecessor'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_strategy_control_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior UUID; paused BOOLEAN; pinned UUID;
BEGIN
 IF NOT NEW.registry_scope THEN RETURN NEW; END IF;
 PERFORM 1 FROM record_strategy_registry WHERE id=1 FOR UPDATE;
 SELECT id INTO prior FROM record_learning_review_controls WHERE registry_scope ORDER BY event_ordinal DESC LIMIT 1;
 IF prior IS DISTINCT FROM NEW.prior_event_id THEN RAISE EXCEPTION 'strategy registry event conflict'; END IF;
 IF NEW.package_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM record_strategy_package_seals WHERE package_id=NEW.package_id)
 THEN RAISE EXCEPTION 'strategy control package is not sealed'; END IF;
 SELECT kind='PAUSE' INTO paused FROM record_learning_review_controls
  WHERE registry_scope AND kind IN ('PAUSE','RESUME') ORDER BY event_ordinal DESC LIMIT 1;
 SELECT CASE WHEN kind='PIN' THEN package_id END INTO pinned FROM record_learning_review_controls
  WHERE registry_scope AND kind IN ('PIN','UNPIN') ORDER BY event_ordinal DESC LIMIT 1;
 IF (NEW.kind='PAUSE' AND coalesce(paused,false))
  OR (NEW.kind='RESUME' AND NOT coalesce(paused,false))
  OR (NEW.kind='UNPIN' AND pinned IS NULL)
 THEN RAISE EXCEPTION 'invalid strategy control transition'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_strategy_package_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior record_global_strategy_packages;
BEGIN
 IF NEW.supersedes_id IS NULL AND EXISTS(SELECT 1 FROM record_global_strategy_packages)
 THEN RAISE EXCEPTION 'global strategy package already bootstrapped'; END IF;
 IF NEW.supersedes_id IS NULL AND NEW.version<>1 THEN RAISE EXCEPTION 'package version requires predecessor'; END IF;
 IF NEW.supersedes_id IS NOT NULL THEN SELECT * INTO prior FROM record_global_strategy_packages WHERE id=NEW.supersedes_id;
  IF prior.id IS NULL OR prior.logical_id<>NEW.logical_id OR prior.version+1<>NEW.version THEN RAISE EXCEPTION 'invalid package predecessor'; END IF;
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_strategy_rollback_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a record_learning_regression_assessments;
BEGIN
 SELECT * INTO a FROM record_learning_regression_assessments WHERE id=NEW.assessment_id;
 IF a.id IS NULL OR a.subject_kind<>'LIVE' OR a.live_package_id<>NEW.current_package_id
  OR (NOT NEW.forced AND NOT a.rollback_satisfied)
  OR NOT EXISTS(SELECT 1 FROM record_strategy_package_seals WHERE package_id=NEW.target_package_id)
 THEN RAISE EXCEPTION 'rollback evidence mismatch'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_strategy_rollback_seal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r record_strategy_rollback_decisions; current record_global_strategy_packages; expected UUID;
BEGIN
 SELECT * INTO r FROM record_strategy_rollback_decisions WHERE id=NEW.rollback_id;
 SELECT * INTO current FROM record_global_strategy_packages WHERE id=r.current_package_id;
 SELECT package_id INTO expected FROM record_strategy_rollback_candidates WHERE rollback_id=NEW.rollback_id AND eligible
  ORDER BY confidence DESC,package_id ASC LIMIT 1;
 IF expected IS NULL OR expected<>r.target_package_id
  OR (SELECT count(*) FROM record_strategy_rollback_candidates WHERE rollback_id=NEW.rollback_id)<>NEW.candidate_count
  OR EXISTS(SELECT 1 FROM record_strategy_rollback_candidates c
    JOIN record_global_strategy_packages p ON p.id=c.package_id
    WHERE c.rollback_id=NEW.rollback_id AND c.eligible
      AND (p.logical_id<>current.logical_id OR p.version>=current.version OR p.created_at>current.created_at
        OR EXISTS(SELECT 1 FROM record_strategy_rollback_decisions prior WHERE prior.current_package_id=p.id)))
 THEN RAISE EXCEPTION 'rollback target is not highest confidence eligible package'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.supply_after_fact()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='supply_batches' THEN
  IF NEW.slot>1 THEN
   INSERT INTO supply_plan_changes SELECT NEW.id,NEW.experiment_id,f.batch_id,f.id,f.payload->'prior_plan',NEW.plan FROM supply_feedback f WHERE f.id=NEW.feedback_id;
  END IF;
 ELSIF TG_TABLE_NAME='supply_outcomes' THEN
  UPDATE supply_plans SET state=NEW.reason WHERE experiment_id=NEW.experiment_id;
  UPDATE supply_candidates SET stopped=true WHERE experiment_id=NEW.experiment_id AND NOT deep_started;
 ELSIF NEW.outcome='QUALIFIED' AND (SELECT count(*) FROM record_current_supply_qualifications WHERE experiment_id=NEW.experiment_id AND outcome='QUALIFIED')=50 THEN
  INSERT INTO supply_outcomes(experiment_id,command_key,reason,achieved,batches_used,businesses_discovered)
  SELECT NEW.experiment_id,NEW.fact_id,'TARGET_50_REACHED',50,(SELECT count(*) FROM supply_batches WHERE experiment_id=NEW.experiment_id),(SELECT count(*) FROM supply_candidates WHERE experiment_id=NEW.experiment_id);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.supply_call_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE binding supply_operations;
BEGIN
 IF EXISTS(SELECT 1 FROM gov_operations WHERE id=NEW.operation_id AND gate_kind IN ('SUPPLY','CONTACT')) AND EXISTS(SELECT 1 FROM supply_plans WHERE experiment_id=NEW.experiment_id) THEN
  PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
  SELECT * INTO binding FROM supply_operations WHERE operation_id=NEW.operation_id;
  IF binding.config_id IS DISTINCT FROM NEW.config_id THEN RAISE EXCEPTION 'supply call not bound to exact configuration'; END IF;
  IF (TG_OP='INSERT' OR (OLD.state='RESERVED' AND NEW.state='DISPATCHED')) AND NOT EXISTS(SELECT 1 FROM supply_plans WHERE experiment_id=NEW.experiment_id AND state='ACTIVE') THEN RAISE EXCEPTION 'terminal supply'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.supply_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p supply_plans; b supply_batches; i supply_identities; f supply_facts; v supply_facts; cl supply_facts; c supply_candidates; fb supply_feedback; op gov_operations; cfg gov_configs; payload jsonb; expected text; total integer; item jsonb; prior jsonb; diff jsonb; dim text;
BEGIN
 PERFORM 1 FROM gov_experiments WHERE id=NEW.experiment_id FOR UPDATE;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='supply_plans' THEN
   IF (to_jsonb(NEW)-'state')<>(to_jsonb(OLD)-'state') OR OLD.state<>'ACTIVE' OR NOT EXISTS(SELECT 1 FROM supply_outcomes WHERE experiment_id=NEW.experiment_id AND reason=NEW.state) THEN RAISE EXCEPTION 'invalid supply transition'; END IF;
  ELSIF TG_TABLE_NAME='supply_batches' THEN
   IF (to_jsonb(NEW)-ARRAY['stage','completed_at'])<>(to_jsonb(OLD)-ARRAY['stage','completed_at']) OR (OLD.completed_at IS NOT NULL AND NEW.completed_at IS DISTINCT FROM OLD.completed_at) OR NOT ((OLD.stage='CONTACT' AND NEW.stage IN ('EMAIL_RETRY_READY','QUALIFICATION','DONE')) OR (OLD.stage='QUALIFICATION' AND NEW.stage IN ('QUALIFICATION_RETRY_READY','DONE'))) THEN RAISE EXCEPTION 'invalid batch transition'; END IF;
   IF OLD.stage='CONTACT' AND EXISTS(SELECT 1 FROM supply_candidates cand LEFT JOIN supply_contacts t ON t.candidate_id=cand.id WHERE cand.batch_id=NEW.id AND (t.candidate_id IS NULL OR t.outcome='SOURCE_FAILURE')) THEN RAISE EXCEPTION 'unresolved contact gate'; END IF;
   IF NEW.stage='QUALIFICATION' AND (SELECT count(*) FROM supply_contacts WHERE experiment_id=NEW.experiment_id AND outcome='SUPPORTED')<50 THEN RAISE EXCEPTION 'email shortage'; END IF;
   IF NEW.stage IN ('EMAIL_RETRY_READY','QUALIFICATION_RETRY_READY') AND NOT EXISTS(SELECT 1 FROM supply_feedback WHERE batch_id=NEW.id AND gate=CASE WHEN NEW.stage='EMAIL_RETRY_READY' THEN 'EMAIL' ELSE 'QUALIFICATION' END) THEN RAISE EXCEPTION 'missing feedback'; END IF;
  ELSIF TG_TABLE_NAME='supply_candidates' THEN
   IF (to_jsonb(NEW)-ARRAY['deep_started','stopped'])<>(to_jsonb(OLD)-ARRAY['deep_started','stopped']) OR (OLD.deep_started AND NOT NEW.deep_started) OR (OLD.stopped AND NOT NEW.stopped) THEN RAISE EXCEPTION 'immutable candidate intent'; END IF;
   IF NEW.deep_started AND NOT OLD.deep_started THEN
    IF NEW.stopped OR NOT EXISTS(SELECT 1 FROM supply_plans WHERE experiment_id=NEW.experiment_id AND state='ACTIVE') OR NOT EXISTS(SELECT 1 FROM supply_contacts WHERE candidate_id=NEW.id AND outcome='SUPPORTED') OR (SELECT count(*) FROM supply_contacts WHERE experiment_id=NEW.experiment_id AND outcome='SUPPORTED')<50 OR NOT EXISTS(SELECT 1 FROM supply_batches WHERE experiment_id=NEW.experiment_id AND stage='QUALIFICATION') THEN RAISE EXCEPTION 'deep work denied'; END IF;
   END IF;
  ELSE RAISE EXCEPTION 'immutable supply fact'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO p FROM supply_plans WHERE experiment_id=NEW.experiment_id;
 IF TG_TABLE_NAME='supply_plans' THEN
  IF NEW.state<>'ACTIVE' OR NOT supply_plan_valid(NEW.initial_plan,NEW.experiment_id) OR NOT supply_filters_valid(NEW.allowed,NEW.experiment_id) OR NOT NEW.allowed @> (NEW.initial_plan->'filters') OR NOT EXISTS(SELECT 1 FROM supply_references WHERE id=NEW.verification_policy_id AND kind='VERIFICATION_POLICY') THEN RAISE EXCEPTION 'invalid supply plan'; END IF;
 ELSIF TG_TABLE_NAME='supply_identities' THEN
  IF NOT EXISTS(SELECT 1 FROM supply_references WHERE id=NEW.provenance_ref AND experiment_id=NEW.experiment_id AND kind='INDEPENDENT_SOURCE' AND mode=NEW.mode) THEN RAISE EXCEPTION 'missing permitted provenance'; END IF;
 ELSIF TG_TABLE_NAME='supply_facts' THEN
  SELECT * INTO i FROM supply_identities WHERE id=NEW.identity_id;
  IF i.mode<>NEW.mode THEN RAISE EXCEPTION 'mixed evidence mode'; END IF;
  IF NEW.kind='SOURCE_EMAIL' AND NEW.contact_ref<>NEW.id THEN RAISE EXCEPTION 'source contact identity'; END IF;
  IF NEW.kind IN ('VERIFIED','VERIFICATION_REJECTED') AND (NOT EXISTS(SELECT 1 FROM supply_facts WHERE id=NEW.contact_ref AND identity_id=NEW.identity_id AND kind='SOURCE_EMAIL' AND observed_at<=NEW.observed_at) OR NOT EXISTS(SELECT 1 FROM supply_references WHERE id=NEW.policy_ref AND kind='VERIFICATION_POLICY')) THEN RAISE EXCEPTION 'invalid verification lineage'; END IF;
  IF NEW.kind IN ('QUALIFIED','REJECTED_FIT','REJECTED_EVIDENCE') AND NOT EXISTS(SELECT 1 FROM supply_references WHERE id=NEW.policy_ref AND kind='QUALIFICATION_RULE') THEN RAISE EXCEPTION 'invalid qualification rule'; END IF;
 ELSIF TG_TABLE_NAME='supply_batches' THEN
  IF p.state IS DISTINCT FROM 'ACTIVE' OR NEW.stage<>'CONTACT' OR NOT supply_plan_valid(NEW.plan,NEW.experiment_id) OR NOT p.allowed @> (NEW.plan->'filters') OR NEW.plan->>'qualification_rule_id'<>p.initial_plan->>'qualification_rule_id' THEN RAISE EXCEPTION 'invalid batch plan'; END IF;
  IF NEW.slot=1 THEN
   IF EXISTS(SELECT 1 FROM supply_batches WHERE experiment_id=NEW.experiment_id) OR NEW.plan<>p.initial_plan THEN RAISE EXCEPTION 'initial batch conflict'; END IF;
  ELSE
   SELECT * INTO b FROM supply_batches WHERE experiment_id=NEW.experiment_id ORDER BY slot DESC LIMIT 1;
   SELECT * INTO fb FROM supply_feedback WHERE id=NEW.feedback_id;
   IF fb.experiment_id IS DISTINCT FROM NEW.experiment_id OR fb.batch_id IS DISTINCT FROM b.id OR fb.payload IS DISTINCT FROM supply_feedback_payload(b.id,fb.gate) OR (NEW.slot=2 AND (b.slot<>1 OR b.stage<>'EMAIL_RETRY_READY' OR fb.gate<>'EMAIL')) OR (NEW.slot=3 AND (b.slot NOT IN (1,2) OR b.stage<>'QUALIFICATION_RETRY_READY' OR fb.gate<>'QUALIFICATION')) THEN RAISE EXCEPTION 'stale or wrong feedback'; END IF;
   prior:=b.plan->'filters'; diff:='[]'::jsonb;
   FOR item IN SELECT value FROM jsonb_array_elements(prior || (NEW.plan->'filters')) LOOP
    IF (prior @> jsonb_build_array(item)) <> ((NEW.plan->'filters') @> jsonb_build_array(item)) THEN diff:=diff || jsonb_build_array(item); END IF;
   END LOOP;
   IF jsonb_array_length(diff)=0 THEN RAISE EXCEPTION 'cosmetic plan change'; END IF;
   FOR item IN SELECT * FROM jsonb_array_elements(diff) LOOP
    dim:=item->>'dimension';
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fb.payload->'performance') x WHERE x->>'dimension'=dim AND x->>'reason' NOT IN ('SUPPORTED','QUALIFIED','PENDING','SOURCE_FAILURE') AND EXISTS(SELECT 1 FROM jsonb_array_elements(prior) y WHERE y->>'dimension'=dim AND y->>'value'=x->>'value')) THEN RAISE EXCEPTION 'unjustified plan change'; END IF;
   END LOOP;
  END IF;
 ELSIF TG_TABLE_NAME='supply_candidates' THEN
  SELECT * INTO b FROM supply_batches WHERE id=NEW.batch_id;
  SELECT * INTO f FROM supply_facts WHERE id=NEW.clearance_id;
  IF p.state IS DISTINCT FROM 'ACTIVE' OR b.stage<>'CONTACT' OR f.kind NOT IN ('IDENTITY_CLEAR','IDENTITY_EXCLUDED') OR NEW.deep_started OR NEW.stopped OR NOT supply_filters_valid(NEW.observations,NEW.experiment_id) OR NOT (b.plan->'filters') @> NEW.observations OR NEW.ordinal<>(SELECT count(*)+1 FROM supply_candidates WHERE batch_id=NEW.batch_id) THEN RAISE EXCEPTION 'candidate admission denied'; END IF;
 ELSIF TG_TABLE_NAME='supply_contacts' THEN
  SELECT * INTO c FROM supply_candidates WHERE id=NEW.candidate_id;
  SELECT * INTO b FROM supply_batches WHERE id=c.batch_id;
  SELECT * INTO i FROM supply_identities WHERE id=c.identity_id;
  SELECT * INTO cl FROM supply_facts WHERE id=c.clearance_id;
  SELECT * INTO f FROM supply_facts WHERE id=NEW.source_id;
  SELECT * INTO v FROM supply_facts WHERE id=NEW.verification_id;
  IF p.state IS DISTINCT FROM 'ACTIVE' OR b.stage<>'CONTACT' OR f.identity_id<>c.identity_id THEN RAISE EXCEPTION 'contact scope or phase'; END IF;
  expected:=CASE WHEN cl.kind='IDENTITY_EXCLUDED' AND f.id=cl.id THEN 'IDENTITY_EXCLUDED' WHEN cl.kind='IDENTITY_CLEAR' AND f.kind='EMAIL_ABSENT' THEN 'EMAIL_NOT_FOUND' WHEN cl.kind='IDENTITY_CLEAR' AND f.kind='SOURCE_FAILURE' THEN 'SOURCE_FAILURE' WHEN cl.kind='IDENTITY_CLEAR' AND f.kind='SOURCE_EMAIL' AND v.identity_id=c.identity_id AND v.contact_ref=f.id AND v.policy_ref=p.verification_policy_id THEN CASE v.kind WHEN 'VERIFIED' THEN 'SUPPORTED' WHEN 'VERIFICATION_REJECTED' THEN 'VERIFICATION_REJECTED' END END;
  IF expected IS NULL OR NEW.outcome<>expected OR (NEW.verification_id IS NOT NULL)<>(expected IN ('SUPPORTED','VERIFICATION_REJECTED')) OR NEW.resolved_at<greatest(i.observed_at,cl.observed_at,f.observed_at,coalesce(v.observed_at,f.observed_at)) OR NEW.resolved_at>=NEW.valid_until OR NEW.valid_until<>least(i.valid_until,cl.valid_until,f.valid_until,coalesce(v.valid_until,f.valid_until)) THEN RAISE EXCEPTION 'invalid contact evidence'; END IF;
 ELSIF TG_TABLE_NAME='supply_contact_failures' THEN
  IF NOT EXISTS(SELECT 1 FROM supply_candidates cand JOIN supply_facts proof ON proof.id=NEW.source_id AND proof.identity_id=cand.identity_id WHERE cand.id=NEW.candidate_id AND proof.kind='SOURCE_FAILURE') THEN RAISE EXCEPTION 'invalid failure lineage'; END IF;
 ELSIF TG_TABLE_NAME='supply_qualifications' THEN
  SELECT * INTO c FROM supply_candidates WHERE id=NEW.candidate_id;
  SELECT * INTO f FROM supply_facts WHERE id=NEW.fact_id;
  IF NOT f.observed_at<=NEW.accepted_at OR NEW.accepted_at>=f.valid_until OR NOT EXISTS(SELECT 1 FROM supply_contacts WHERE candidate_id=c.id AND resolved_at<=NEW.accepted_at AND valid_until>NEW.accepted_at) OR EXISTS(SELECT 1 FROM record_current_supply_qualifications WHERE experiment_id=NEW.experiment_id AND accepted_at>NEW.accepted_at) OR EXISTS(SELECT 1 FROM record_current_supply_qualifications q JOIN supply_facts proof ON proof.id=q.fact_id JOIN supply_contacts t ON t.candidate_id=q.candidate_id WHERE q.experiment_id=NEW.experiment_id AND q.outcome='QUALIFIED' AND (proof.valid_until<=NEW.accepted_at OR t.valid_until<=NEW.accepted_at)) THEN RAISE EXCEPTION 'expired accepted evidence'; END IF;
  IF p.state IS DISTINCT FROM 'ACTIVE' OR NOT c.deep_started OR c.stopped OR f.identity_id<>c.identity_id OR f.kind<>NEW.outcome OR f.policy_ref::text<>p.initial_plan->>'qualification_rule_id' OR NOT EXISTS(SELECT 1 FROM supply_contacts WHERE candidate_id=c.id AND outcome='SUPPORTED') OR NOT EXISTS(SELECT 1 FROM supply_batches WHERE experiment_id=NEW.experiment_id AND stage='QUALIFICATION') OR (NEW.outcome='QUALIFIED' AND (SELECT count(*) FROM record_current_supply_qualifications WHERE experiment_id=NEW.experiment_id AND outcome='QUALIFIED')>=50) THEN RAISE EXCEPTION 'qualification denied'; END IF;
 ELSIF TG_TABLE_NAME='supply_feedback' THEN
  SELECT * INTO b FROM supply_batches WHERE id=NEW.batch_id;
  payload:=supply_feedback_payload(NEW.batch_id,NEW.gate);
  IF p.state IS DISTINCT FROM 'ACTIVE' OR NEW.payload IS DISTINCT FROM payload OR (payload->>'deficit')::int NOT BETWEEN 1 AND 50 OR b.slot=3 OR (NEW.gate='EMAIL' AND (b.slot<>1 OR b.stage<>'CONTACT')) OR (NEW.gate='QUALIFICATION' AND b.stage<>'QUALIFICATION') OR EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'reasons') x WHERE x->>'reason' IN ('PENDING','SOURCE_FAILURE') OR (NEW.gate='QUALIFICATION' AND x->>'reason'='SUPPORTED')) THEN RAISE EXCEPTION 'incomplete or malformed feedback'; END IF;
 ELSIF TG_TABLE_NAME='supply_operations' THEN
  SELECT * INTO op FROM gov_operations WHERE id=NEW.operation_id;
  SELECT * INTO cfg FROM gov_configs WHERE id=NEW.config_id;
  IF op.gate_kind IS DISTINCT FROM (CASE WHEN NEW.kind='CONTACT' THEN 'CONTACT' ELSE 'SUPPLY' END) OR p.state IS DISTINCT FROM 'ACTIVE' THEN RAISE EXCEPTION 'unbound supply gate'; END IF;
  IF (NEW.kind='DISCOVERY' AND cfg.capability NOT IN ('BRAVE_LOCAL_DISCOVERY','BRAVE_COMPANY_DISCOVERY','BRAVE_WEB_COVERAGE')) OR (NEW.kind='CONTACT' AND cfg.capability NOT IN ('BRAVE_LOCAL_DISCOVERY','BRAVE_COMPANY_DISCOVERY','HUNTER_DOMAIN_SEARCH','HUNTER_EMAIL_FINDER','HUNTER_COMPANY_ENRICHMENT','HUNTER_PERSON_ENRICHMENT','HUNTER_EMAIL_VERIFICATION','FIRECRAWL_MAP','FIRECRAWL_PAGE_CAPTURE','FIRECRAWL_PDF_CAPTURE','FIRECRAWL_JS_RETRIEVAL')) OR (NEW.kind='DEEP' AND cfg.capability NOT IN ('OPENAI_GENERATE','FIRECRAWL_MAP','FIRECRAWL_PAGE_CAPTURE','FIRECRAWL_PDF_CAPTURE','FIRECRAWL_JS_RETRIEVAL','BRAVE_WEB_COVERAGE')) THEN RAISE EXCEPTION 'work capability mismatch'; END IF;
 ELSIF TG_TABLE_NAME='supply_discovery_completions' THEN
  IF p.state IS DISTINCT FROM 'ACTIVE' OR NOT supply_filters_valid(jsonb_build_array(NEW.filter),NEW.experiment_id) OR NOT EXISTS(SELECT 1 FROM supply_batches WHERE id=NEW.batch_id AND stage='CONTACT' AND plan->'filters' @> jsonb_build_array(NEW.filter)) OR NOT EXISTS(SELECT 1 FROM supply_references WHERE id=(NEW.filter->>'value')::uuid AND mode=NEW.mode) THEN RAISE EXCEPTION 'invalid discovery completion'; END IF;
 ELSIF TG_TABLE_NAME='supply_plan_changes' THEN
  IF NOT EXISTS(SELECT 1 FROM supply_batches batch JOIN supply_feedback brief ON brief.id=batch.feedback_id WHERE batch.id=NEW.batch_id AND batch.plan=NEW.new_plan AND brief.id=NEW.feedback_id AND brief.batch_id=NEW.source_batch_id AND brief.payload->'prior_plan'=NEW.prior_plan) THEN RAISE EXCEPTION 'invalid plan change lineage'; END IF;
 ELSIF TG_TABLE_NAME='supply_outcomes' THEN
  SELECT count(*) INTO total FROM record_current_supply_qualifications WHERE experiment_id=NEW.experiment_id AND outcome='QUALIFIED';
  IF NEW.reason='EMAIL_SUPPLY_INSUFFICIENT_AFTER_BATCH_2' AND (NOT EXISTS(SELECT 1 FROM supply_batches WHERE experiment_id=NEW.experiment_id AND slot=2 AND stage='CONTACT') OR (SELECT count(*) FROM supply_contacts WHERE experiment_id=NEW.experiment_id AND outcome='SUPPORTED')>=50 OR EXISTS(SELECT 1 FROM supply_candidates cand LEFT JOIN supply_contacts t ON t.candidate_id=cand.id WHERE cand.experiment_id=NEW.experiment_id AND (t.candidate_id IS NULL OR t.outcome='SOURCE_FAILURE'))) THEN RAISE EXCEPTION 'invalid email shortage'; END IF;
  IF NEW.reason='QUALIFIED_SUPPLY_INSUFFICIENT_AFTER_BATCH_3' AND (NOT EXISTS(SELECT 1 FROM supply_batches WHERE experiment_id=NEW.experiment_id AND slot=3 AND stage='QUALIFICATION') OR EXISTS(SELECT 1 FROM supply_contacts t LEFT JOIN record_current_supply_qualifications q ON q.candidate_id=t.candidate_id WHERE t.experiment_id=NEW.experiment_id AND t.outcome='SUPPORTED' AND q.candidate_id IS NULL)) THEN RAISE EXCEPTION 'invalid qualification shortage'; END IF;
  IF p.state IS DISTINCT FROM 'ACTIVE' OR NEW.achieved<>total OR NEW.batches_used<>(SELECT count(*) FROM supply_batches WHERE experiment_id=NEW.experiment_id) OR NEW.businesses_discovered<>(SELECT count(*) FROM supply_candidates WHERE experiment_id=NEW.experiment_id) OR NEW.reason='ACTIVE' THEN RAISE EXCEPTION 'invalid outcome facts'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.gov_validate_call_json(item gov_calls)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE operation gov_operations; config gov_configs; a jsonb; r jsonb; m jsonb; u jsonb; actor jsonb;
BEGIN
 SELECT * INTO operation FROM gov_operations WHERE id=item.operation_id;
 SELECT * INTO config FROM gov_configs WHERE id=item.config_id;
 a:=item.attribution; r:=item.request; m:=item.result_metadata;
 IF operation.agent_id IS NOT NULL THEN
  actor:=jsonb_build_object('schema_version',1,'kind','agent','agent_run_id',operation.agent_id::text);
 ELSE
  actor:=jsonb_build_object('schema_version',1,'kind','system','service',operation.service);
 END IF;
 IF NOT gov_json_object(a,ARRAY['schema_version','experiment_id','workflow_run_id','operation_run_id',
   'operation_run_kind','actor','correlation_id','logical_operation_id','config_version','deadline'])
   OR NOT (a->>'experiment_id'=item.experiment_id::text AND a->>'workflow_run_id'=item.workflow_id::text
    AND a->>'operation_run_id'=item.operation_id::text AND a->>'config_version'=item.config_version::text
    AND a->>'logical_operation_id'=item.logical_operation_id::text AND a->>'operation_run_kind'=operation.kind
    AND a->'actor'=actor AND a->'actor'->>'schema_version'='1') IS TRUE
   OR NOT gov_json_uuid(a->'correlation_id') OR NOT gov_json_time(a->'deadline') THEN
  RAISE EXCEPTION 'invalid governance attribution' USING ERRCODE='23514';
 END IF;
 IF NOT gov_json_object(r,ARRAY['schema_version','config_ref','requested_count'])
   OR NOT (r->>'config_ref'=item.config_id::text AND jsonb_typeof(r->'requested_count')='number'
    AND r->>'requested_count' ~ '^[1-9][0-9]*$' AND (r->>'requested_count')::integer BETWEEN 1 AND 100
    AND r->'requested_count'=config.data->'requested_count') IS TRUE THEN
  RAISE EXCEPTION 'invalid governance request metadata' USING ERRCODE='23514';
 END IF;
 IF m IS NULL THEN RETURN; END IF;
 IF NOT gov_json_object(m,ARRAY['schema_version','capability','external_request_id','started_at','finished_at','status','error_code','usage'])
   OR NOT (m->>'capability'=config.capability AND item.state IN ('DISPATCHED','RECONCILING','FINAL')
    AND item.token IS NOT NULL AND item.finished_at IS NOT NULL
    AND m->>'status' IN ('SUCCEEDED','REFUSED','FAILED')
    AND ((m->>'status'='SUCCEEDED' AND m->'error_code'='null'::jsonb)
     OR (m->>'status'<>'SUCCEEDED' AND m->>'error_code' IN ('DENIED','CAPABILITY_MISMATCH','TIMEOUT','UNAVAILABLE','MALFORMED_RESPONSE','REFUSED','WRITE_AUTHORITY_REQUIRED','INCOMPLETE_RESULT','CANCELLED_RESULT')))
    AND (m->'external_request_id'='null'::jsonb OR (jsonb_typeof(m->'external_request_id')='string' AND m->>'external_request_id' ~ '^[A-Za-z0-9_-]{1,100}$'))
    AND jsonb_typeof(m->'usage')='array') IS TRUE
   OR NOT gov_json_time(m->'started_at') OR NOT gov_json_time(m->'finished_at') THEN
  RAISE EXCEPTION 'invalid governance result metadata' USING ERRCODE='23514';
 END IF;
 IF (m->>'finished_at')::timestamptz < (m->>'started_at')::timestamptz THEN
  RAISE EXCEPTION 'invalid governance result timing' USING ERRCODE='23514';
 END IF;
 FOR u IN SELECT value FROM jsonb_array_elements(m->'usage') LOOP
  IF NOT gov_json_object(u,ARRAY['schema_version','component','quantity','currency','cost','knowledge','observation_key'])
    OR NOT gov_json_uuid(u->'observation_key') OR NOT gov_json_quantity(u->'quantity') OR NOT gov_json_quantity(u->'cost')
    OR NOT (u->>'currency'=item.currency AND u->>'knowledge' IN ('ESTIMATE','FINAL','UNAVAILABLE')
      AND ((u->>'knowledge'='UNAVAILABLE' AND u->'cost'='null'::jsonb)
       OR (u->>'knowledge'<>'UNAVAILABLE' AND u->'cost'<>'null'::jsonb))) IS TRUE THEN
   RAISE EXCEPTION 'invalid governance usage metadata' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM gov_usage existing WHERE existing.call_id=item.id
    AND existing.observation_key::text=u->>'observation_key' AND existing.component=u->>'component'
    AND existing.currency=u->>'currency' AND existing.knowledge=u->>'knowledge'
    AND existing.quantity IS NOT DISTINCT FROM (u->>'quantity')::numeric
    AND existing.cost IS NOT DISTINCT FROM (u->>'cost')::numeric) THEN
   RAISE EXCEPTION 'governance usage metadata binding' USING ERRCODE='23514';
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.supply_filters_valid(items jsonb, exp uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE item jsonb;
BEGIN
 IF jsonb_typeof(items) <> 'array' OR jsonb_array_length(items)>100 THEN RETURN false; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(items)) <> (SELECT count(DISTINCT v) FROM jsonb_array_elements(items) v) THEN RETURN false; END IF;
 FOR item IN SELECT * FROM jsonb_array_elements(items) LOOP
  IF NOT gov_json_object(item, ARRAY['schema_version','dimension','value']) OR item->>'schema_version'<>'1' OR NOT gov_json_uuid(item->'value') OR NOT EXISTS(SELECT 1 FROM supply_references r WHERE r.id=(item->>'value')::uuid AND r.experiment_id=exp AND r.kind='FILTER' AND r.dimension=item->>'dimension') THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.record_org_block_reason(org uuid, recipient uuid, exp uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE canonical uuid:=record_org_canonical(org);
BEGIN
 IF EXISTS(SELECT 1 FROM record_org_suppressions s WHERE s.global_scope OR record_org_canonical(s.organization_id)=canonical OR s.recipient_id=recipient OR s.recipient_id IN (SELECT recipient_id FROM record_org_recipient_sources rs WHERE record_org_canonical(rs.organization_id)=canonical)) THEN RETURN 'SUPPRESSED'; END IF;
 IF EXISTS(SELECT 1 FROM record_org_observations o JOIN record_org_reservations r ON r.id=o.reservation_id WHERE o.outcome='CONFIRMED' AND (record_org_canonical(r.organization_id)=canonical OR r.recipient_id=recipient OR r.recipient_id IN (SELECT recipient_id FROM record_org_recipient_sources rs WHERE record_org_canonical(rs.organization_id)=canonical))) THEN RETURN 'CONTACTED'; END IF;
 IF EXISTS(SELECT 1 FROM record_org_observations o JOIN record_org_reservations r ON r.id=o.reservation_id WHERE o.outcome='AMBIGUOUS' AND NOT EXISTS(SELECT 1 FROM record_org_observations resolution WHERE resolution.reconciles_id=o.id AND resolution.outcome IN ('CONFIRMED','NO_EFFECT')) AND (record_org_canonical(r.organization_id)=canonical OR r.recipient_id=recipient OR r.recipient_id IN (SELECT recipient_id FROM record_org_recipient_sources rs WHERE record_org_canonical(rs.organization_id)=canonical))) THEN RETURN 'CONTACT_AMBIGUOUS'; END IF;
 IF EXISTS(SELECT 1 FROM record_org_reservations r WHERE record_org_reservation_live(r.id) AND r.experiment_id IS DISTINCT FROM exp AND (record_org_canonical(r.organization_id)=canonical OR r.recipient_id=recipient OR r.recipient_id IN (SELECT recipient_id FROM record_org_recipient_sources rs WHERE record_org_canonical(rs.organization_id)=canonical))) THEN RETURN 'RESERVED_ELSEWHERE'; END IF;
 IF EXISTS(SELECT 1 FROM record_org_conflicts conflict WHERE (record_org_canonical(conflict.organization_id)=canonical OR record_org_canonical(conflict.matched_id)=canonical) AND NOT EXISTS(SELECT 1 FROM record_org_identity_decisions d WHERE d.conflict_id=conflict.id)) THEN RETURN 'IDENTITY_CONFLICT'; END IF;
 IF canonical IS DISTINCT FROM org THEN RETURN 'IDENTITY_MERGED'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.record_org_email_lookup(retained_id uuid, idx integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE value text;
BEGIN
 PERFORM record_org_require_key();
 IF record_org_source_current(retained_id,'EMAIL') IS NOT TRUE THEN RAISE EXCEPTION 'email source unavailable'; END IF;
 SELECT values->>idx INTO value FROM gov_retained WHERE id=retained_id;
 IF value IS NULL OR value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'unsupported email'; END IF;
 RETURN record_org_lookup(value);
END $function$

CREATE OR REPLACE FUNCTION public.record_org_snapshot(retained_id uuid, idx integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE result jsonb; r gov_retained; grant_data jsonb;
BEGIN
 PERFORM record_org_require_key();
 IF record_org_source_current(retained_id,'COMPANY') IS NOT TRUE THEN RAISE EXCEPTION 'organization source unavailable'; END IF;
 SELECT * INTO r FROM gov_retained WHERE id=retained_id;
 IF idx<0 OR idx>=jsonb_array_length(r.values) THEN RAISE EXCEPTION 'source index invalid'; END IF;
 result:=(r.values->>idx)::jsonb;
 IF record_json_exact(result,ARRAY['schema_version','canonical_name','canonical_domain','organization_kind','identifiers','aliases','locations']) IS NOT TRUE
 OR result->>'schema_version'<>'1' OR record_nonempty_text(result->'canonical_name') IS NOT TRUE
 OR (result->>'organization_kind' IN ('LOCAL_BUSINESS','ONLINE_COMPANY','HYBRID','UNKNOWN')) IS NOT TRUE
 OR jsonb_typeof(result->'identifiers') IS DISTINCT FROM 'array' OR jsonb_typeof(result->'aliases') IS DISTINCT FROM 'array' OR jsonb_typeof(result->'locations') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'invalid organization snapshot'; END IF;
 IF jsonb_array_length(result->'identifiers')>30 OR jsonb_array_length(result->'aliases')>50 OR jsonb_array_length(result->'locations')>100
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'identifiers') ident WHERE record_json_exact(ident,ARRAY['schema_version','kind','namespace','value']) IS NOT TRUE OR ident->>'schema_version' IS DISTINCT FROM '1' OR (ident->>'kind' IN ('REGISTERED_ID','PROVIDER_ID','OFFICIAL_URL')) IS NOT TRUE OR record_nonempty_text(ident->'namespace') IS NOT TRUE OR record_nonempty_text(ident->'value') IS NOT TRUE OR (ident->>'kind'='REGISTERED_ID' AND ident->>'namespace' !~ '^[A-Z]{2}$'))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'aliases') alias WHERE record_json_exact(alias,ARRAY['schema_version','kind','value']) IS NOT TRUE OR alias->>'schema_version' IS DISTINCT FROM '1' OR (alias->>'kind' IN ('NAME','DOMAIN','URL','FORMER_NAME')) IS NOT TRUE OR record_nonempty_text(alias->'value') IS NOT TRUE)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'locations') location WHERE record_json_exact(location,ARRAY['schema_version','branch_name','country_code','city','address','latitude','longitude']) IS NOT TRUE OR location->>'schema_version' IS DISTINCT FROM '1' OR (location->>'country_code' ~ '^[A-Z]{2}$') IS NOT TRUE OR record_nonempty_text(location->'city') IS NOT TRUE OR record_nonempty_text(location->'address') IS NOT TRUE OR (location->>'latitude' IS NULL)<>(location->>'longitude' IS NULL) OR (location->>'latitude')::numeric NOT BETWEEN -90 AND 90 OR (location->>'longitude')::numeric NOT BETWEEN -180 AND 180)
 THEN RAISE EXCEPTION 'invalid typed identity content'; END IF;
 SELECT data INTO grant_data FROM gov_grants WHERE id=r.grant_id AND version=r.grant_version;
 IF (result->>'canonical_domain' IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'aliases') a WHERE a->>'kind' IN ('DOMAIN','URL')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(result->'identifiers') a WHERE a->>'kind'='OFFICIAL_URL')) AND (NOT grant_data->'storage_fields' ? 'URL' OR NOT EXISTS(SELECT 1 FROM gov_calls call JOIN gov_configs config ON config.id=call.config_id WHERE call.id=r.call_id AND config.data->'intended_use'->'required_fields' ? 'URL'))
 THEN RAISE EXCEPTION 'URL storage entitlement required'; END IF;
 RETURN result;
EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid organization snapshot';
END $function$

CREATE OR REPLACE FUNCTION public.record_org_source_current(retained_id uuid, required_field text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE r gov_retained; g gov_grants; c gov_calls; config gov_configs;
BEGIN
 SELECT * INTO r FROM gov_retained WHERE id=retained_id;
 IF r.id IS NULL THEN RETURN false; END IF;
 SELECT * INTO g FROM gov_grants WHERE id=r.grant_id AND version=r.grant_version;
 SELECT * INTO c FROM gov_calls WHERE id=r.call_id;
 SELECT * INTO config FROM gov_configs WHERE id=c.config_id;
 PERFORM 1 FROM gov_authorities WHERE account=g.account AND capability=g.capability FOR SHARE;
 RETURN COALESCE(r.field=required_field AND r.expires_at>record_org_now() AND g.effective_at<=record_org_now() AND g.expires_at>record_org_now()
  AND (g.data->>'outbound_use_permitted')::boolean AND g.data->'storage_fields' ? required_field
  AND config.account=g.account AND config.capability=g.capability
  AND config.data->'intended_use'->>'purpose'=g.data->>'purpose'
  AND config.data->'intended_use'->'required_fields' ? required_field
  AND g.data->>'purpose' IN ('RESEARCH','LEAD_DISCOVERY','CONTACT_DISCOVERY')
  AND NOT EXISTS(SELECT 1 FROM gov_grants newer WHERE newer.data->>'supersedes_id'=g.id::text AND newer.effective_at<=record_org_now() AND newer.expires_at>record_org_now())
  AND c.grant_id=g.id AND c.grant_version=g.version AND c.state='FINAL'
  AND EXISTS(SELECT 1 FROM gov_authorities WHERE account=g.account AND capability=g.capability AND enabled)
  AND NOT EXISTS(SELECT 1 FROM gov_grant_events e WHERE e.grant_id=g.id AND e.grant_version=g.version AND (e.data->>'effective_at')::timestamptz<=record_org_now() AND e.data->>'kind'<>'ACTIVATED'),false);
END $function$

CREATE OR REPLACE FUNCTION public.record_profile_number(value jsonb, max_value numeric, places integer, positive boolean DEFAULT false, inclusive boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE number numeric;
BEGIN
 IF jsonb_typeof(value) IS DISTINCT FROM 'string' OR (value#>>'{}') !~ '^(0|[1-9][0-9]*)(\.[0-9]+)?$' THEN RETURN false; END IF;
 IF length(value#>>'{}')>32 THEN RETURN false; END IF;
 number := (value#>>'{}')::numeric;
 RETURN number>=0 AND (NOT positive OR number>0) AND scale(number)<=places
    AND ((inclusive AND number<=max_value) OR (NOT inclusive AND number<max_value));
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.record_org_lookup(value text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM record_org_require_key();
 IF value IS NULL OR length(btrim(value))=0 THEN RAISE EXCEPTION 'missing identity value'; END IF;
 RETURN encode(hmac(convert_to(lower(btrim(regexp_replace(value,'[[:space:]]+',' ','g'))),'UTF8'),convert_to(current_setting('alon.organization_key'),'UTF8'),'sha256'),'hex');
END $function$
